    "core_concepts": [
      {
        "term": "Trigonometric identity",
        "definition": "An equation involving trigonometric functions that is true for every value of the variable in the common domain of both sides.",
        "example": "sin²x + cos²x = 1"
      },
      {
        "term": "Trigonometric equation",
        "definition": "An equation containing trigonometric functions in which specific values of the variable are sought.",
        "example": "sinx = 1/2"
      },
      {
        "term": "Solution set",
        "definition": "The complete set of values that satisfy a trigonometric equation.",
        "example": "For cosx = 0, the general solution is x = π/2 + nπ, where n ∈ ℤ."
      },
      {
        "term": "Equivalent transformation",
        "definition": "A transformation that preserves all solutions under the relevant restrictions. Dividing by a possibly zero expression or squaring may not be equivalent without separate checks."
      }
    ],
    "identity_toolkit": [
      {
        "category": "Reciprocal identities",
        "formulas": [
          "cscx = 1/sinx, when sinx ≠ 0",
          "secx = 1/cosx, when cosx ≠ 0",
          "cotx = 1/tanx, when tanx ≠ 0",
          "sinx · cscx = 1, when sinx ≠ 0",
          "cosx · secx = 1, when cosx ≠ 0",
          "tanx · cotx = 1, when tanx ≠ 0"
        ]
      },
      {
        "category": "Quotient identities",
        "formulas": [
          "tanx = sinx/cosx, when cosx ≠ 0",
          "cotx = cosx/sinx, when sinx ≠ 0"
        ]
      },
      {
        "category": "Fundamental Pythagorean identities",
        "formulas": [
          "sin²x + cos²x = 1",
          "1 + tan²x = sec²x, when cosx ≠ 0",
          "1 + cot²x = csc²x, when sinx ≠ 0"
        ]
      },
      {
        "category": "Parity identities",
        "formulas": [
          "sin(−x) = −sinx",
          "cos(−x) = cosx",
          "tan(−x) = −tanx",
          "csc(−x) = −cscx",
          "sec(−x) = secx",
          "cot(−x) = −cotx"
        ]
      },
      {
        "category": "Angle-sum and angle-difference identities",
        "formulas": [
          "sin(a ± b) = sina cosb ± cosa sinb",
          "cos(a ± b) = cosa cosb ∓ sina sinb",
          "tan(a ± b) = (tana ± tanb)/(1 ∓ tana tanb)"
        ],
        "teaching_note": "Use these formulas only where the expressions on both sides are defined."
      },
      {
        "category": "Double-angle identities",
        "formulas": [
          "sin2x = 2sinx cosx",
          "cos2x = cos²x − sin²x",
          "cos2x = 1 − 2sin²x",
          "cos2x = 2cos²x − 1",
          "tan2x = 2tanx/(1 − tan²x)"
        ]
      }
    ],
    "equation_solving_framework": {
      "workflow": [
        "State the interval or whether a general solution is required.",
        "Identify the structure: one trigonometric function, a multiple angle, a quadratic, a factorable expression, or a rational expression.",
        "Choose a suitable identity and transform the equation.",
        "Before dividing by an expression, record the values for which it equals zero and consider those values separately.",
        "Reduce the equation to a basic algebraic or trigonometric equation.",
        "Find reference angles and use the unit circle or periodicity to obtain all candidates.",
        "Substitute candidates into the original equation and reject undefined or extraneous values.",
        "Present the answer in the requested interval or in general form."
      ],
      "common_structures": [
        {
          "structure": "sinx = a, cosx = a, or tanx = a",
          "method": "Use reference angles, the unit circle, quadrant signs, and periodicity."
        },
        {
          "structure": "Equations containing sin2x or cos2x",
          "method": "Rewrite the multiple angle using a double-angle identity and solve the resulting equation."
        },
        {
          "structure": "A quadratic in sinx or cosx",
          "method": "Let u = sinx or u = cosx, factor or use the quadratic formula, and solve for u in [−1, 1]."
        },
        {
          "structure": "A factorable trigonometric expression",
          "method": "Factor before dividing. For example, sinx(2cosx − 1) = 0 gives two separate equations."
        },
        {
          "structure": "A homogeneous equation such as a sin²x + b sinx cosx + c cos²x = 0",
          "method": "If appropriate, divide by cos²x and use tanx, but separately check cosx = 0 if it was excluded by division."
        },
        {
          "structure": "a sinx + b cosx = c",
          "method": "As an extension, write the left side as R sin(x + φ) or R cos(x − φ), then solve the resulting sinusoid."
        }
      ],
      "verification_rules": [
        "Retain the domain of the original expression.",
        "Treat every division as potentially lossy.",
        "Check solutions obtained by squaring or taking square roots.",
        "Include all valid quadrants.",
        "Use radians unless the problem explicitly specifies degrees.",
        "Include n ∈ ℤ in every general solution."
      ]
