    {
      "title": "Separable equation",
      "problem": "Solve y′ = 2xy with y(0) = 1.",
      "solution_steps": [
        "For y ≠ 0, separate variables: dy/y = 2x dx.",
        "Integrate: ln|y| = x² + C.",
        "Thus y = Ae^(x²).",
        "Apply y(0) = 1 to obtain A = 1.",
        "Therefore y = e^(x²), which also satisfies the equation at x = 0."
      ],
      "verification": "y′ = 2xe^(x²) = 2xy and y(0) = e^0 = 1."
    },
    {
      "title": "First-order linear equation",
      "problem": "Solve y′ + 2xy = x.",
      "solution_steps": [
        "The integrating factor is μ(x) = e^(x²), because ∫2x dx = x².",
        "Multiply the equation by e^(x²): (y e^(x²))′ = x e^(x²).",
        "Integrate: y e^(x²) = (1/2)e^(x²) + C.",
        "Divide by e^(x²): y = 1/2 + Ce^(−x²)."
      ],
      "verification": "y′ = −2xCe^(−x²), while y′ + 2xy = −2xCe^(−x²) + x + 2xCe^(−x²) = x."
    },
    {
      "title": "Second-order initial-value problem",
      "problem": "Solve y″ − 5y′ + 6y = 0, y(0) = 1, y′(0) = 0.",
      "solution_steps": [
        "The characteristic equation is r² − 5r + 6 = (r − 2)(r − 3) = 0.",
        "The general solution is y = C₁e^(2x) + C₂e^(3x).",
        "From y(0) = 1, C₁ + C₂ = 1.",
        "From y′(0) = 0, 2C₁ + 3C₂ = 0.",
        "Solving gives C₁ = 3 and C₂ = −2.",
        "Therefore y = 3e^(2x) − 2e^(3x)."
      ],
      "verification": "The general form satisfies the differential equation, and the constants satisfy both initial conditions."
    },
    {
      "title": "Existence and uniqueness",
      "problem": "Consider y′ = f(x,y), y(x₀) = y₀. Decide when a local unique solution is guaranteed.",
      "solution_steps": [
        "Check that f(x,y) is continuous in a neighborhood of (x₀,y₀) for local existence.",
        "Check that ∂f/∂y is continuous in a neighborhood of (x₀,y₀) for the standard uniqueness guarantee.",
        "If both conditions hold on a suitable rectangle, the Picard–Lindelöf theorem guarantees a unique local solution."
      ],
      "interpretation": "Failure of the continuity conditions does not automatically prove that no solution exists; it means that this particular theorem does not provide the guarantee."
    }
