  "key_points": [
    {
      "key_point_id": "K1",
      "title": "First-order necessary condition",
      "explanation": "For an interior local extremum of a differentiable function f(x,y), both partial derivatives must vanish. This condition identifies candidates, not guaranteed extrema."
    },
    {
      "key_point_id": "K2",
      "title": "Hessian classification",
      "explanation": "Let H be the Hessian matrix and D = det(H). If D > 0 and fₓₓ > 0, the point is a local minimum. If D > 0 and fₓₓ < 0, it is a local maximum. If D < 0, it is a saddle point. If D = 0, the test is inconclusive."
    },
    {
      "key_point_id": "K3",
      "title": "Degenerate critical points",
      "explanation": "When D = 0, use path analysis, Taylor expansion, factorization, convexity, or higher-order derivatives. A degenerate point may be a minimum, maximum, or saddle point."
    },
    {
      "key_point_id": "K4",
      "title": "Absolute extrema on a region",
      "explanation": "If a function is continuous on a nonempty compact domain, the Extreme Value Theorem guarantees absolute extrema. The candidate list must include interior critical points, regular boundary points, corners, and nondifferentiable points."
    },
    {
      "key_point_id": "K5",
      "title": "Boundary analysis",
      "explanation": "A boundary may be represented by equations, parameterized curves, or finitely many line segments. Restricting the objective to the boundary converts the problem to one-variable or constrained analysis."
    },
    {
      "key_point_id": "K6",
      "title": "Lagrange multiplier idea",
      "explanation": "At a regular constrained extremum, the gradient of the objective is normal to the constraint curve, so ∇f and ∇g are parallel: ∇f = λ∇g."
    },
    {
      "key_point_id": "K7",
      "title": "Constraint qualification",
      "explanation": "The standard Lagrange multiplier argument requires ∇g ≠ 0 at the candidate. For multiple constraints, the constraint gradients are usually required to be linearly independent."
    },
    {
      "key_point_id": "K8",
      "title": "KKT conditions",
      "explanation": "For maximizing f with constraints gᵢ ≤ 0, one common convention is L = f − Σλᵢgᵢ with λᵢ ≥ 0. Conditions include stationarity, primal feasibility, dual feasibility, and complementary slackness. Under a suitable constraint qualification these are necessary, not automatically sufficient."
    },
    {
      "key_point_id": "K9",
      "title": "Local versus global conclusions",
      "explanation": "The Hessian test usually establishes only local behavior. A global claim requires comparison of all feasible candidates or a stronger argument such as convexity, monotonicity, or a global inequality."
    }
