  "common_misconceptions_and_corrections": [
    {
      "misconception": "The electron travels around the nucleus like a small planet.",
      "correction": "In quantum mechanics, the electron is described by a wavefunction. The squared magnitude of the wavefunction gives a probability density, not a definite classical orbit."
    },
    {
      "misconception": "A wavefunction is directly observable.",
      "correction": "Observables are represented by operators. Measurement outcomes correspond to eigenvalues, while the wavefunction is not itself a directly measured physical observable."
    },
    {
      "misconception": "All transitions between any two energy levels are equally strong.",
      "correction": "Transition intensity depends on coupling, symmetry, dipole-moment change, population, and other factors. Selection rules predict strong or symmetry-forbidden transitions under particular approximations."
    },
    {
      "misconception": "A harmonic oscillator has equally spaced levels because the potential is parabolic.",
      "correction": "The harmonic approximation gives equally spaced levels, but real molecular bonds are anharmonic and therefore show decreasing level spacing at higher vibrational energies."
    },
    {
      "misconception": "A molecular spectrum is a set of perfectly sharp ideal lines.",
      "correction": "Experimental spectra are affected by finite lifetime, collisions, temperature, pressure, solvent interactions, unresolved rotational structure, and instrumental resolution."
    },
    {
      "misconception": "The wavelength of a spectral line is a molecular property independent of the transition.",
      "correction": "Wavelength depends on the specific energy-level difference. Even within one molecule, different rotational and vibrational transitions produce different wavelengths."
    }
