{
  "title": "Quantum Chemistry: Time-Independent Perturbation Theory",
  "knowledge_point": "Perturbation theory",
  "lesson_overview": {
    "duration_minutes": 90,
    "audience": "Advanced undergraduate or beginning graduate students in quantum chemistry, chemistry, or theoretical physics",
    "central_question": "How can an exactly solvable unperturbed system be used to approximate a quantum system with a weak additional interaction?",
    "scope": "The lesson focuses on time-independent, nondegenerate and degenerate Rayleigh–Schrödinger perturbation theory. Time-dependent perturbation theory is briefly mentioned as a follow-up topic.",
    "prerequisites": [
