  "teaching_objectives": {
    "knowledge_objectives": [
      "Define the decomposition H(λ) = H₀ + λV and distinguish the unperturbed Hamiltonian, perturbation, and expansion parameter.",
      "Explain why perturbation theory is appropriate when the coupling to other states is weak.",
      "State the first- and second-order energy corrections for a nondegenerate level.",
      "State the first-order correction to the wavefunction.",
      "Explain why degenerate perturbation theory requires diagonalization within the degenerate subspace.",
      "Identify the main conditions under which perturbation theory becomes unreliable."
    ],
    "skill_objectives": [
      "Calculate first- and second-order energy corrections for simple quantum systems.",
      "Calculate or interpret first-order wavefunction corrections.",
      "Estimate whether an energy gap is large enough for perturbation theory to be valid.",
      "Compare perturbative results with exact or numerically diagonalized results.",
      "Communicate the assumptions and limitations behind an approximation."
    ],
    "application_objectives": [
      "Recognize applications to weak external fields, small relativistic effects, weak state couplings, and selected electron-correlation problems.",
      "Diagnose near-degeneracy and replace ordinary perturbation theory with degenerate perturbation theory or numerical diagonalization."
    ]
  },
  "key_points": [
    {
      "topic": "Separation of the Hamiltonian",
      "explanation": "The full Hamiltonian is written as H(λ) = H₀ + λV, where H₀ is exactly solvable, V represents the additional interaction, and λ measures its strength."
    },
    {
      "topic": "Power-series expansion",
      "explanation": "The energy and wavefunction are expanded in powers of λ: Eₙ(λ) = Eₙ⁽⁰⁾ + λEₙ⁽¹⁾ + λ²Eₙ⁽²⁾ + … and ψₙ(λ) = ψₙ⁽⁰⁾ + λψₙ⁽¹⁾ + …."
    },
    {
      "topic": "First-order energy correction",
      "explanation": "For a nondegenerate state, Eₙ⁽¹⁾ = ⟨n|V|n⟩. This is the diagonal expectation value of the perturbation in the unperturbed state."
    },
    {
      "topic": "Second-order energy correction",
      "explanation": "Eₙ⁽²⁾ = Σₘ≠ₙ |⟨m|V|n⟩|² / (Eₙ⁽⁰⁾ − Eₘ⁽⁰⁾). The sum runs over all other states, discrete or continuous."
    },
    {
      "topic": "First-order wavefunction correction",
      "explanation": "In intermediate normalization, |ψₙ⁽¹⁾⟩ = Σₘ≠ₙ [⟨m|V|n⟩ / (Eₙ⁽⁰⁾ − Eₘ⁽⁰⁾)]|m⟩."
    },
    {
      "topic": "Degenerate perturbation theory",
      "explanation": "If the unperturbed level is degenerate, the nondegenerate formula is invalid because the energy denominator can vanish. The perturbation matrix must first be diagonalized within the degenerate subspace."
    },
    {
      "topic": "Validity criterion",
      "explanation": "A useful heuristic is |λ⟨m|V|n⟩| ≪ |Eₙ⁽⁰⁾ − Eₘ⁽⁰⁾|. A small perturbation parameter alone is not sufficient if the relevant energy gaps are very small."
    },
    {
      "topic": "Perturbation theory as an approximation",
      "explanation": "Perturbation theory is most reliable for weak coupling and well-separated levels. The truncated series should be checked against exact or numerical results whenever possible."
    }
  ],
  "key_difficulties": [
    {
      "difficulty": "Understanding what must be small",
      "reason": "Students often assume that λ must be small numerically, without considering the size of matrix elements or energy gaps.",
      "teaching_response": "Emphasize the ratio of level mixing, approximately |λVₘₙ| / |Eₙ⁽⁰⁾ − Eₘ⁽⁰⁾|, rather than λ alone."
