        "Eₙ(λ) = Eₙ⁽⁰⁾ + λEₙ⁽¹⁾ + λ²Eₙ⁽²⁾ + …",
        "|ψₙ(λ)⟩ = |ψₙ⁽⁰⁾ + λ|ψₙ⁽¹⁾ + λ²|ψₙ⁽²⁾⟩ + …"
