{
  "title": "CRISPR-Cas9 Mechanism and Applications in Genomic Editing",
  "lesson_type": "Interactive introductory biology lesson",
  "target_audience": "Advanced high-school students or introductory undergraduate students",
  "class_duration_minutes": 90,
  "prerequisites": [
    "Basic knowledge of DNA structure and complementary base pairing",
    "Basic understanding of genes, proteins, and gene expression",
    "Introduction to DNA replication and double-strand breaks"
  ],
  "learning_objectives": {
    "knowledge": [
      "Define CRISPR and explain the main functions of Cas9 and guide RNA",
      "Describe the sequence of events that allow Cas9 to recognize and cut a target DNA molecule",
      "Explain the roles of the guide RNA, PAM sequence, and Cas9 nuclease domains",
      "Compare non-homologous end joining and homology-directed repair",
      "Distinguish gene knockout, gene knock-in, base editing, prime editing, and CRISPR-based gene regulation"
    ],
    "skills": [
      "Identify a protospacer and PAM sequence in a simplified DNA example",
      "Construct a candidate guide RNA spacer from a DNA target sequence",
      "Predict whether a deletion or insertion is more likely to disrupt a gene",
      "Select an appropriate CRISPR application for a given research problem",
      "Evaluate an editing strategy in terms of efficiency, specificity, delivery, and ethics"
    ],
    "attitudes": [
      "Appreciate that powerful genome-editing technologies require responsible use",
      "Recognize both the potential benefits and the risks of modifying DNA",
      "Understand that scientific decisions should consider safety, fairness, consent, and environmental effects"
    ]
  },
  "key_points": [
    {
      "point": "CRISPR-Cas9 is a programmable DNA-targeting system",
      "explanation": "The guide RNA directs Cas9 to a complementary DNA sequence, while Cas9 performs the cleavage."
    },
    {
      "point": "The guide RNA contains a variable spacer and a constant scaffold",
      "explanation": "The spacer provides sequence specificity through complementary base pairing. The scaffold interacts with Cas9 and helps position the nuclease at the target."
    },
    {
      "point": "A PAM sequence is required for target recognition",
      "explanation": "For the commonly used Streptococcus pyogenes Cas9, or SpCas9, the PAM is generally 5-prime-NGG-3-prime. The PAM is recognized by Cas9 and is not part of the guide RNA spacer."
    },
    {
      "point": "Cas9 creates a targeted double-strand DNA break",
      "explanation": "After the guide RNA binds the complementary DNA strand, the HNH and RuvC domains cut opposite DNA strands, normally near the PAM-proximal end of the target."
    },
    {
      "point": "The cellular repair pathway determines the final editing outcome",
      "explanation": "Non-homologous end joining can create insertions or deletions, whereas homology-directed repair can use a donor DNA template to introduce a designed sequence."
    },
    {
      "point": "CRISPR technologies have multiple applications",
      "explanation": "Applications include gene knockout, targeted insertion, precise sequence replacement, gene repression or activation, diagnostics, disease modeling, agriculture, and biotechnology."
    }
  ],
  "difficult_points": [
