        "term": "CRISPR",
        "definition": "Clustered regularly interspaced short palindromic repeats; a genetic system found in some microorganisms that stores and uses sequences for defense."
      },
      {
        "term": "Cas9",
        "definition": "A DNA-cutting protein used in CRISPR gene editing and guided by a complementary RNA."
      },
      {
        "term": "crRNA",
        "definition": "CRISPR RNA containing a sequence that can guide recognition of a matching foreign nucleic acid."
      },
      {
        "term": "tracrRNA",
        "definition": "A small RNA that helps process crRNA and supports formation of the Cas9 RNA complex in natural type II systems."
      },
      {
        "term": "sgRNA",
        "definition": "Synthetic single-guide RNA commonly used for genome editing; it combines a crRNA-derived spacer with a tracrRNA-derived scaffold."
      },
      {
        "term": "Spacer",
        "definition": "The sequence-specific portion of the guide RNA that pairs with a complementary target DNA sequence."
      },
      {
        "term": "PAM",
        "definition": "Protospacer adjacent motif; a short DNA sequence recognized by Cas9. For SpCas9, a common example is 5-prime-NGG-3-prime."
      },
      {
        "term": "R-loop",
        "definition": "A local DNA structure in which one DNA strand is displaced and paired with guide RNA."
      },
      {
        "term": "Double-strand break",
        "definition": "A break affecting both strands of DNA, often created by Cas9."
      },
      {
        "term": "NHEJ",
        "definition": "Non-homologous end joining, a DNA-repair pathway that reconnects broken ends and can introduce small insertions or deletions."
      },
      {
        "term": "HDR",
        "definition": "Homology-directed repair, a DNA-repair pathway that can use a donor template to introduce a defined sequence change."
      },
      {
        "term": "Off-target edit",
        "definition": "An unintended edit at a site other than the intended target."
      },
      {
        "term": "Mosaicism",
        "definition": "A condition in which different cells within one individual carry different genetic states or different edited and unedited versions."
      }
    ],
    "teacher_mnemonic": [
      "Guide RNA = address",
      "PAM = recognition checkpoint",
      "Cas9 = molecular cutter",
      "DNA-repair pathway = final editor",
      "Sequencing and functional testing = verification"
    ]
  }
}

