    "vocabulary": [
      {
        "term": "Epigenetic regulation",
        "definition": "Regulation of gene activity or chromatin state that occurs without changing the underlying DNA nucleotide sequence."
      },
      {
        "term": "Chromatin",
        "definition": "DNA combined with histones and other proteins; its organization determines how accessible regulatory DNA is."
      },
      {
        "term": "Nucleosome",
        "definition": "A structural unit consisting of DNA wrapped around a histone octamer."
      },
      {
        "term": "Euchromatin",
        "definition": "Relatively open chromatin that is generally accessible for transcription."
      },
      {
        "term": "Heterochromatin",
        "definition": "Relatively compact chromatin that is generally less accessible for transcription."
      },
      {
        "term": "CpG methylation",
        "definition": "Addition of a methyl group to cytosine at a CpG site; in mammalian promoters it is often associated with repression."
      },
      {
        "term": "Histone modification",
        "definition": "A chemical modification of histone proteins that can alter chromatin interactions and recruit regulatory proteins."
      },
      {
        "term": "Chromatin remodeling",
        "definition": "ATP-dependent repositioning, removal, or restructuring of nucleosomes."
      },
      {
        "term": "Long noncoding RNA",
        "definition": "A noncoding RNA longer than approximately 200 nucleotides that can guide regulatory complexes to specific genomic regions."
      },
      {
        "term": "Genomic imprinting",
        "definition": "Parent-of-origin-specific gene expression produced by differential epigenetic regulation of the maternal and paternal alleles."
      },
      {
        "term": "X-chromosome inactivation",
        "definition": "Chromosome-scale dosage compensation in which one X chromosome is largely silenced in female mammalian cells."
      },
      {
        "term": "Epigenome editing",
        "definition": "Targeted modification of epigenetic marks at a selected genomic locus, often using a catalytic domain fused to a programmable DNA-binding protein."
      }
    ]
  },
  "key_points": [
    {
      "id": "K1",
      "point": "Epigenetic regulation is sequence-independent regulation.",
      "explanation": "Epigenetic mechanisms change how accessible a gene is or how actively it is transcribed without changing the DNA sequence. These states can sometimes persist through cell division, but they are not necessarily permanent or inherited through many generations.",
      "representative_example": "A neuron and a skin cell can contain the same genome but use different regulatory programs because their chromatin states and transcription factors differ."
    },
    {
      "id": "K2",
      "point": "Chromatin organization is a physical regulator of transcription.",
      "explanation": "DNA is packaged around histones into nucleosomes. Open euchromatin permits greater access by transcription factors and RNA polymerase, whereas compact heterochromatin restricts access.",
      "representative_example": "A promoter located within accessible chromatin is more likely to be active than the same promoter embedded in compact chromatin."
    },
    {
      "id": "K3",
      "point": "DNA methylation is often repressive at mammalian promoters but is context-dependent.",
      "explanation": "In mammals, methylation of cytosines at CpG sites can block regulatory protein binding and recruit methyl-CpG-binding proteins and histone-modifying complexes. Methylation in gene bodies, enhancers, or other organisms can have different consequences.",
      "representative_example": "Promoter CpG hypermethylation is frequently associated with silencing in cancer, while gene-body methylation can coexist with active transcription."
    },
    {
      "id": "K4",
      "point": "Histone modifications regulate chromatin through chemical and protein recognition.",
      "explanation": "Histone acetylation generally loosens chromatin by reducing interactions between positively charged histones and negatively charged DNA. Histone methylation does not have one universal effect; its consequence depends on the modified residue and the surrounding chromatin context.",
      "representative_example": "H3K27ac is commonly associated with active enhancers and promoters, whereas H3K27me3 and H3K9me3 are commonly associated with repression."
    },
    {
      "id": "K5",
      "point": "ATP-dependent remodeling complexes change nucleosome position and composition.",
      "explanation": "Remodeling complexes use energy from ATP to expose or conceal regulatory sequences. They can reposition nucleosomes, remove or exchange histone variants, and alter the distance between enhancers and promoters.",
      "representative_example": "A remodeling complex can expose a promoter-bound transcription factor site that was previously inaccessible."
    },
    {
      "id": "K6",
      "point": "Noncoding RNAs can connect sequence recognition with epigenetic regulation.",
      "explanation": "MicroRNAs commonly regulate RNA stability or translation after transcription. Long noncoding RNAs can guide chromatin-modifying complexes to specific loci or organize large chromosomal regions.",
      "representative_example": "The XIST long noncoding RNA coats one X chromosome in female mammals and helps recruit silencing machinery."
    },
    {
      "id": "K7",
      "point": "Cell identity and development depend on stable yet dynamic epigenetic programs.",
      "explanation": "During differentiation, cells establish distinct patterns of accessible and inaccessible DNA. These patterns support stable cell identity while still allowing responses to developmental signals and environmental conditions.",
      "representative_example": "Different cell types can maintain different expression profiles even when they contain the same genomic DNA sequence."
    },
    {
      "id": "K8",
      "point": "Epigenetic data must be interpreted with appropriate controls and multiple assays.",
      "explanation": "A correlation between a mark and gene expression does not by itself prove that the mark causes the expression change. Strong conclusions require perturbation experiments, biological replicates, expression measurements, and independent validation.",
      "representative_example": "A decrease in promoter methylation after targeted demethylation, together with increased RNA, supports a causal contribution but should still be checked for off-target and compensatory effects."
    }
  ],
