    },
    {
      "difficulty": "Writing a valid base case",
      "reason": "Students may continue making recursive calls until a stack overflow occurs.",
      "teaching_strategy": "Emphasize that every sequence of recursive calls must eventually reach a stopping condition."
    },
    {
      "difficulty": "Understanding return order",
      "reason": "Students often follow calls forward but do not understand how values are returned while the call stack unwinds.",
      "teaching_strategy": "Use colored call cards, stack cups, and a step-by-step execution table."
    },
    {
      "difficulty": "Choosing the recursive input",
      "reason": "Students may call the function with an input that is not smaller or simpler.",
      "teaching_strategy": "Ask, 'Does this call guarantee that the next call will be closer to the stopping condition?'"
