    "core_teaching_content": {
      "central_question": "How can a distributed system preserve security when messages are delayed, duplicated, reordered, delivered to compromised nodes, or processed by services that do not fully trust one another?",
      "security_properties": [
        {
          "property": "Confidentiality",
          "definition": "Information is disclosed only to authorized entities.",
          "distributed_system_example": "A service-to-service message containing a customer record is encrypted and only authorized workloads can decrypt it."
        },
        {
          "property": "Integrity",
          "definition": "Unauthorized modification of data, messages, or system state is prevented or detected.",
          "distributed_system_example": "A replica detects that a log record has been modified before accepting it."
        },
        {
          "property": "Availability",
          "definition": "Authorized users can obtain required services within an acceptable time.",
          "distributed_system_example": "Rate limiting and load shedding preserve essential operations during a traffic surge."
        },
        {
          "property": "Authenticity",
          "definition": "The system can verify the identity or origin of a user, workload, or message.",
          "distributed_system_example": "A workload presents a valid certificate to authenticate itself to another workload."
        },
        {
          "property": "Authorization",
          "definition": "An authenticated entity is permitted to perform a specific action on a specific resource.",
          "distributed_system_example": "A caller may read an order but cannot change its payment status."
        },
        {
          "property": "Accountability and evidentiary support",
          "definition": "Actions can be attributed to authenticated entities and investigated afterward.",
          "distributed_system_example": "Administrative actions are recorded in access-controlled, tamper-evident audit logs.",
          "note": "Digital signatures support evidence of origin, but legal or organizational non-repudiation also depends on identity proofing, key custody, timestamps, and policy."
        }
      ],
      "common_attacks": [
        {
