          "objective": "Impersonate legitimate users or workloads.",
          "example": "Stealing a bearer token or private service credential."
        },
        {
          "attack": "Replay attack",
          "objective": "Cause a valid old request to be processed again.",
          "example": "Resending a previously valid payment instruction."
        },
        {
          "attack": "Tampering",
          "objective": "Modify messages, binaries, configuration, or replicated state.",
          "example": "Changing an order amount or corrupting a replicated log record."
        },
        {
          "attack": "Denial of service or resource exhaustion",
          "objective": "Prevent timely access to services.",
          "example": "Flooding a gateway, broker, connection pool, lock table, or expensive cryptographic endpoint."
        },
        {
          "attack": "Compromised node or insider",
          "objective": "Abuse legitimate access while bypassing normal behavior.",
          "example": "A malicious worker returns fabricated results or reads unauthorized data."
        },
        {
          "attack": "Sybil or Byzantine behavior",
          "objective": "Manipulate replication, voting, or identity mechanisms.",
          "example": "A participant sends conflicting messages to different peers."
        },
        {
          "attack": "Software and supply-chain compromise",
          "objective": "Insert malicious code or vulnerable dependencies.",
          "example": "Deploying an unauthorized service image containing an exploitable library."
        },
        {
          "attack": "Side-channel leakage",
          "objective": "Infer secrets from observable system behavior.",
          "example": "Using response timing or shared-resource contention to infer information."
        }
      ],
      "control_mechanisms": [
        {
          "mechanism": "Authenticated secure transport",
          "examples": [
            "TLS 1.3 or an approved equivalent",
            "Mutual TLS for workload identity",
            "Correct hostname, certificate-chain, and validity checks"
