      ],
      "distributed_specific_issues": [
        "There may be no single trusted perimeter that covers all services and administrative domains.",
        "Messages can be delayed, reordered, duplicated, or delivered long after they were created.",
        "Components may fail by crashing, hanging, returning incorrect results, or behaving maliciously.",
        "A timeout does not reveal whether the remote operation failed, timed out, or already committed.",
        "Retries can duplicate non-idempotent operations or amplify congestion.",
        "Clocks may be skewed or unsynchronized, so timestamp validation needs a defined trust model.",
        "Key directories, certificate authorities, identity providers, and secret stores can become high-value dependencies.",
        "Audit evidence is distributed across services and must be protected against tampering and clock inconsistencies.",
        "Data placement can introduce legal, privacy, and jurisdiction concerns in addition to technical concerns."
      ],
      "design_principles": [
        "Do not trust messages merely because they came from the network or an internal address.",
        "Authenticate every principal and authorize every sensitive operation independently.",
        "Apply least privilege and separation of duties.",
        "Use defense in depth rather than relying on a single security control.",
        "Use secure defaults and fail securely when validation or dependencies fail.",
        "Minimize exposed services, data, privileges, and trusted code.",
        "Make security controls observable, testable, and replaceable.",
        "Plan for key compromise, credential leakage, and service unavailability.",
        "Preserve evidence without allowing audit systems to become new attack targets."
      ],
      "secure_protocol_checklist": [
        "Which principals are being authenticated?",
        "How is trust established for their public keys or credentials?",
        "What confidentiality and integrity protections apply to each data flow?",
        "Where do protections terminate?",
        "How is message freshness established?",
        "Are tokens bound to the intended issuer, audience, scope, and operation?",
        "What happens if the remote operation times out?",
        "Can retries duplicate a non-idempotent action?",
        "How are keys rotated and revoked?",
        "What audit evidence and incident response procedures exist?"
      ]
