      ]
    },
    "common_misconceptions": [
      {
        "misconception": "Using HTTPS means the entire distributed system is secure.",
        "correction": "TLS protects only the configured communication paths. Backends, storage systems, endpoints, administrator paths, and downstream services require separate protections."
      },
      {
        "misconception": "A hash encrypts data or prevents an attacker with write access from changing it.",
        "correction": "A plain hash is neither encryption nor a keyed integrity control. An attacker may modify the data and recompute the hash."
      },
      {
        "misconception": "If a token can be decoded, it is authentic.",
        "correction": "Decoding only reads content. The receiver must verify the signature or trusted issuer and validate issuer, audience, expiration, scope, and other relevant claims."
      },
      {
        "misconception": "Digital signatures automatically provide non-repudiation.",
        "correction": "Signatures provide cryptographic evidence of possession of a signing key. Organizational and legal non-repudiation also depends on identity proofing, secure key custody, timestamps, and procedures."
      },
      {
        "misconception": "Replication automatically makes a system Byzantine fault tolerant.",
        "correction": "Ordinary replication primarily addresses crash failures and data redundancy. Byzantine resilience requires stronger protocols and explicit network and participant assumptions."
      },
      {
        "misconception": "Retries are always safe and improve reliability.",
        "correction": "Retries can duplicate non-idempotent operations and overload services. They require deadlines, idempotency, retry budgets, backoff, and jitter."
      },
