  "core_lecture_notes": [
    {
      "section_id": "S1",
      "title": "Motivation and vocabulary",
      "teacher_explanation": [
        "An operating system must support multiple processes, threads, interrupts, device completions, and asynchronous input-output events.",
        "Concurrency is the broader concept of overlapping progress. Parallelism is a special form of simultaneous execution on multiple processing units.",
        "The main challenge is not only making execution fast, but making the result correct and predictable when timing changes."
      ],
      "example": "A single processor can alternate between a browser, an editor, and an input handler. A multicore processor can execute two of those activities simultaneously while still scheduling many more threads.",
      "discussion_prompts": [
        "Can a system be concurrent without being parallel?",
        "Can a system be parallel without being concurrent? In the usual OS interpretation, no.",
        "Which sources of concurrency are created by the operating system itself?"
      ],
      "takeaway": "Concurrency is a property of overlapping progress; parallelism is a property of simultaneous execution."
    },
    {
      "section_id": "S2",
      "title": "Processes, threads, and the scheduler",
      "teacher_explanation": [
        "A process contains a virtual address space and protected resources. A thread is an execution context that can run within a process.",
        "Threads in one process share global variables, heap memory, open files, and code. Each thread has a private stack, program counter, and registers.",
        "The scheduler decides which runnable execution context receives the processor. A context switch saves the state of one context and restores another.",
        "Preemption allows the operating system to interrupt a running thread. Blocking, time slicing, interrupts, and voluntary yielding can also cause scheduling decisions."
      ],
      "comparison": [
        {
          "entity": "Process",
          "characteristic": "Own virtual address space and resource boundary",
          "typical_advantage": "Isolation",
          "typical_cost": "Communication and synchronization require explicit mechanisms such as IPC"
        },
        {
          "entity": "Thread",
          "characteristic": "Execution context within a process",
          "typical_advantage": "Lightweight sharing and communication",
          "typical_cost": "Shared data creates race conditions and synchronization requirements"
        },
        {
          "entity": "Interrupt or device event",
          "characteristic": "Asynchronous event handled by the operating system",
          "typical_advantage": "Supports input-output and timely system response",
          "typical_cost": "May contend with threads or kernel data structures"
        }
      ],
      "discussion_prompts": [
        "What is shared and what is private between two threads in the same process?",
        "What work must occur during a context switch?",
        "Why can a high-priority thread cause a low-priority thread to wait for a long time?"
      ],
      "takeaway": "Scheduling selects execution contexts, while synchronization controls how those contexts interact."
    },
    {
      "section_id": "S3",
      "title": "Shared state, race conditions, and invariants",
      "teacher_explanation": [
        "Shared state is correct only if every permitted interleaving preserves its intended invariant.",
        "A race condition is not merely a program that uses threads. It is a dependence on timing that can produce an incorrect or unpredictable result.",
        "A critical section is the portion of code that accesses shared data and needs protection. The critical-section problem requires mutual exclusion, progress, and bounded waiting.",
        "A useful debugging question is: what must always be true about the shared data, and which operations can temporarily violate that truth?"
      ],
      "pseudocode": [
        "counter = 0",
        "T1: r1 = counter",
        "T1: r1 = r1 + 1",
        "T1: counter = r1",
        "T2: r2 = counter",
        "T2: r2 = r2 + 1",
        "T2: counter = r2"
      ],
      "interleaving_example": [
        "T1 reads counter and receives 0",
        "T2 reads counter and receives 0",
        "T1 writes 1",
        "T2 writes 1"
      ],
      "possible_final_values": [0, 1, 2],
      "intentional_result": "The counter should equal 2 after both increments, but a value of 1 demonstrates a lost update. A value of 0 is also possible if both writes occur after both reads in a schedule with the explicit steps shown.",
      "takeaway": "Protect the entire logical transaction, not just the final assignment."
    },
    {
      "section_id": "S4",
      "title": "Synchronization mechanisms",
      "teacher_explanation": [
        "Hardware primitives such as atomic instructions, test-and-set, and compare-and-swap form the foundation for many software locks.",
        "A mutex is appropriate when one execution context must exclusively modify a shared object.",
        "A semaphore represents a number of permits and is useful when a resource has limited capacity.",
        "A condition variable represents a wait for a state change, not a replacement for checking the state itself.",
        "A lock should protect a clearly defined invariant and should normally be held for a short time. Holding a lock during blocking I/O increases contention and can cause deadlock.",
        "Atomic operations are suitable for simple independent updates, but a compound invariant may require a lock or a higher-level transaction mechanism."
      ],
      "critical_section_requirements": [
        {
          "requirement": "Mutual exclusion",
          "meaning": "At most one execution context enters the protected critical section at a time."
        },
        {
          "requirement": "Progress",
          "meaning": "If the critical section becomes free, some waiting execution context can eventually enter it; unrelated execution contexts do not block it indefinitely."
        },
        {
          "requirement": "Bounded waiting",
          "meaning": "A waiting execution context is eventually selected, subject to the scheduling and fairness properties of the synchronization mechanism."
        }
      ],
      "takeaway": "Choose a primitive based on the invariant and waiting condition, not simply on whether threads are present."
