        "Mutual exclusion protects the buffer structure. Additional signaling or waiting mechanisms handle the full and empty conditions.",
        "A condition-variable solution must use a predicate loop. A notification does not guarantee that a particular waiter runs immediately or that the predicate remains true when it wakes."
      ],
      "semaphore_pseudocode": {
        "definitions": [
          "P(s) is the wait operation, which atomically consumes one permit.",
          "V(s) is the signal operation, which adds one permit."
        ],
        "initialization": [
          "empty = buffer_capacity",
          "full = 0",
          "buffer_lock is unlocked"
        ],
        "producer": [
          "P(empty)",
          "acquire(buffer_lock)",
          "put one item into the buffer",
          "release(buffer_lock)",
          "V(full)"
        ],
        "consumer": [
          "P(full)",
          "acquire(buffer_lock)",
          "remove one item from the buffer",
          "release(buffer_lock)",
          "V(empty)"
        ]
