  "common_misconceptions": [
    {
      "misconception": "Concurrency and parallelism are the same concept.",
      "correction": "Concurrency concerns overlapping progress; parallelism concerns simultaneous execution on multiple processing units."
    },
    {
      "misconception": "A source-level statement such as counter++ is always one indivisible hardware operation.",
      "correction": "It commonly requires load, add, and store steps. It is safe only when the language or platform explicitly guarantees atomic behavior."
    },
    {
      "misconception": "A mutex and a semaphore are interchangeable.",
      "correction": "They have different semantics. A mutex normally models exclusive ownership, while a semaphore models permits or resource counts. A binary semaphore can sometimes implement similar behavior, but the API and reasoning are different."
    },
    {
      "misconception": "Signaling a condition variable guarantees that the signaled thread runs immediately.",
      "correction": "A signal usually makes a waiter eligible to run. It does not guarantee immediate scheduling, and the waiter must recheck the predicate in a loop."
    },
    {
      "misconception": "Using locks automatically prevents all concurrency bugs.",
      "correction": "Locks must protect the correct state, be acquired in a consistent order, and be released by the appropriate execution context. They do not automatically prevent deadlock, starvation, or logic errors."
    },
    {
      "misconception": "volatile provides general thread synchronization.",
      "correction": "Visibility, atomicity, mutual exclusion, and ordering are different properties. Use a mutex, atomic operation, or language-specific memory-ordering mechanism as appropriate."
    },
    {
      "misconception": "Deadlock, livelock, and starvation are synonyms.",
      "correction": "Deadlock is permanent waiting, livelock is active but non-progress, and starvation is indefinite denial of service to one participant while others continue."
    }
  ],
