  "glossary": [
    {
      "term": "Concurrency",
      "definition": "The ability for multiple activities to make progress during overlapping time intervals, whether or not they execute simultaneously."
    },
    {
      "term": "Parallelism",
      "definition": "Simultaneous execution of multiple activities on multiple processing units."
    },
    {
      "term": "Process",
      "definition": "A program instance with its own virtual address space and resource protections."
    },
    {
      "term": "Thread",
      "definition": "An execution context within a process; threads in one process share many resources."
    },
    {
      "term": "Context switch",
      "definition": "Saving the state of one execution context and restoring the state of another so that the processor can run it."
    },
    {
      "term": "Race condition",
      "definition": "A correctness problem in which the result depends on the relative timing of concurrent operations."
    },
    {
      "term": "Atomicity",
      "definition": "The property that an operation is observed as indivisible by other execution contexts."
    },
    {
      "term": "Critical section",
      "definition": "A region of code that accesses shared state and must be protected to preserve correctness."
    },
    {
      "term": "Mutex",
      "definition": "A synchronization object that provides exclusive access to a protected resource, normally with ownership by one thread."
    },
    {
      "term": "Semaphore",
      "definition": "A synchronization object that maintains a count of permits using wait and signal operations."
    },
    {
      "term": "Condition variable",
      "definition": "A synchronization object used to wait until a shared-state predicate becomes true, normally while holding an associated mutex."
    },
    {
      "term": "Deadlock",
      "definition": "A permanent state in which participating execution contexts wait for resources or events that cannot become available."
    },
    {
      "term": "Livelock",
      "definition": "A state in which execution contexts remain active but repeatedly respond to one another without making useful progress."
    },
    {
      "term": "Starvation",
      "definition": "A situation in which one execution context receives insufficient resources or attention and makes no progress while others continue."
    },
    {
      "term": "Safety",
      "definition": "The property that an incorrect state or forbidden event never occurs."
    },
    {
      "term": "Liveness",
      "definition": "The property that a desired event eventually occurs and execution contexts are not indefinitely denied progress."
    }
  ]
}

