      },
      {
        "question": "Does quantum phase estimation require direct measurement of the eigenstate?",
        "expected_answer": "No. It measures an ancilla register after controlled evolution and an inverse QFT, then infers the eigenvalue phase."
      },
      {
        "question": "What kind of problem is Grover's algorithm best suited to?",
        "expected_answer": "Black-box or unstructured search with a coherent marking oracle and no exploitable additional structure."
      },
      {
        "question": "Why does Shor's algorithm need classical post-processing?",
        "expected_answer": "The quantum subroutine estimates an order r; classical continued fractions and greatest-common-divisor calculations use r to obtain a factor."
      }
    ],
    "formative_assessment": [
