{
  "Teaching Material": {
    "topic": "Introduction to Programmable Logic Controllers",
    "course_type": "Foundational lecture and hands-on laboratory",
    "suggested_duration_minutes": 90,
    "learning_context": "This lesson introduces students to the structure, operating principle, and basic programming of PLCs. It is suitable for beginners in industrial automation, electrical engineering, mechatronics, and vocational technology.",
    "prerequisites": [
      "Basic knowledge of Boolean logic",
      "Understanding of normally open and normally closed contacts",
      "Basic electrical circuits",
      "Familiarity with AND, OR, and NOT logic"
    ],
    "teaching_objectives": {
      "knowledge_objectives": [
        "Define a programmable logic controller and describe its industrial applications",
        "Identify the main PLC components, including the CPU, power supply, input module, output module, memory, and programming interface",
        "Explain the PLC scan cycle: input scan, program execution, output update, and communication or diagnostics",
        "Describe the difference between physical input and output addresses and internal memory addresses",
        "Recognize basic ladder logic symbols, including normally open, normally closed, coil, and connector instructions"
      ],
      "skill_objectives": [
        "Draw a basic ladder logic diagram",
        "Assign simulated input and output addresses",
        "Construct a simple AND logic control circuit",
        "Construct a simple OR logic control circuit",
        "Test and troubleshoot a PLC program using a simulator or trainer",
        "Translate a simple control requirement into an I/O table, logic expression, and ladder diagram"
      ],
      "application_objectives": [
        "Explain the role of PLCs in automated machines and production systems",
        "Recognize why PLCs are more flexible and maintainable than fixed relay control circuits",
        "Demonstrate responsible programming practices, including clear addressing, comments, testing, and documentation"
      ]
    },
    "key_points": [
      {
        "point": "PLC purpose",
        "description": "A PLC is an industrial digital controller that reads field inputs, executes stored control instructions, and controls field outputs."
      },
      {
        "point": "PLC architecture",
        "description": "The CPU processes instructions, the input module receives field signals, the output module sends control signals, and memory stores programs, data, and diagnostic information."
      },
      {
        "point": "PLC scan cycle",
        "description": "A typical PLC reads inputs, executes the program in sequence, updates outputs, and then begins the next scan."
      },
      {
        "point": "I/O addressing",
        "description": "Input addresses represent the current state of sensors and switches, while output addresses represent commands for actuators such as lamps, motors, or valves."
      },
      {
        "point": "Ladder logic",
        "description": "Ladder logic represents control logic using horizontal instruction lines and vertical power rails. Each rung is evaluated from left to right."
      },
      {
        "point": "Boolean relationships",
        "description": "Contacts connected in series represent AND logic, while contacts connected in parallel represent OR logic. A NOT function is usually represented by a normally closed contact."
      },
      {
        "point": "Repeatability and flexibility",
        "description": "Changing a PLC program is generally faster and less disruptive than rewiring a fixed relay control circuit."
      }
    ],
    "common_difficulties": [
      {
        "difficulty": "Understanding the continuous scan cycle",
        "explanation": "Students may assume that all instructions execute simultaneously. In fact, the CPU usually executes program instructions in a defined sequence during each scan.",
        "teaching_approach": "Use an animated scan-cycle diagram and a visible status table showing input states, intermediate results, and output states."
      },
      {
        "difficulty": "Confusing physical I/O addresses with memory addresses",
        "explanation": "Students may treat internal bits and physical input points as the same thing.",
        "teaching_approach": "Display a clear I/O map and demonstrate that an input address reflects the physical input, while an internal memory bit stores a calculated result."
      },
      {
        "difficulty": "Understanding normally open and normally closed instructions",
        "explanation": "The instruction name describes the contact instruction in the program, not necessarily the physical switch type.",
        "teaching_approach": "Compare live physical switches with their corresponding PLC contact instructions and use a truth table."
      },
      {
        "difficulty": "Translating control requirements into logic",
        "explanation": "Students may know Boolean expressions but have difficulty converting a written requirement into an I/O list and ladder diagram.",
        "teaching_approach": "Use a four-step method: identify devices, write the I/O table, express the logic, and draw and test the ladder diagram."
      },
      {
        "difficulty": "Overlooking program order and initial states",
        "explanation": "Students may place instructions in an unintended order or assume outputs will remain on when the program first starts.",
        "teaching_approach": "Introduce sequence, initialization, and safe default states before discussing more advanced memory instructions."
      }
    ],
    "teaching_strategies": [
      "Use a short lecture supported by a visual PLC scan-cycle animation.",
      "Connect traditional relay circuits with PLC ladder diagrams to show why PLC control is more flexible.",
      "Use an interactive traffic-light, conveyor, or motor-control simulation.",
      "Organize students into small groups with roles such as control engineer, programmer, panel technician, and tester.",
      "Ask students to predict the output before each simulation run.",
      "Use formative questioning and quick checks throughout the lesson."
    ],
    "required_equipment_and_materials": [
      "PLC simulator or programming software",
      "Optional low-voltage PLC trainer",
      "Projector or large display",
      "Ladder logic diagrams",
      "I/O address tables",
      "Normally open and normally closed switch models",
      "LED indicators or virtual lamps",
      "Boolean logic truth tables",
      "Group worksheets and exit tickets"
    ],
    "safety_notes": [
      "Use a simulator whenever possible.",
      "If physical equipment is used, apply power only under instructor supervision.",
      "Do not connect mains voltage to student PLC inputs or outputs.",
      "Use an instructor-approved low-voltage trainer for practical work.",
      "Keep output loads within the rated voltage and current of the PLC module.",
      "Program in a safe state and initially leave motor-driving outputs disabled.",
      "Do not rely on ordinary PLC logic as a substitute for emergency-stop, guarding, or other required safety devices."
    ],
    "core_content": {
      "introduction": {
        "definition": "A programmable logic controller is a ruggedized digital electronic device that uses stored programs to automate machines and processes.",
        "typical_applications": [
          "Assembly-line control",
          "Conveyor systems",
          "Packaging machines",
          "Traffic-light control",
          "Water and temperature control",
          "Automated warehouses",
          "Industrial robots and machine safety systems"
        ],
        "comparison_with_relay_control": [
          "Relay control requires physical rewiring when requirements change.",
          "PLC control can be modified mainly by editing the program.",
          "PLC systems support compact control, diagnostics, communication, and reusable functions.",
          "Traditional relay knowledge remains useful for understanding PLC logic."
        ]
      },
      "plc_components": [
        {
          "component": "Power supply",
          "function": "Converts the incoming electrical supply into the voltages required by PLC modules."
        },
        {
          "component": "Central processing unit",
          "function": "Reads instructions, performs logic and arithmetic operations, manages communication, and controls PLC operation."
        },
        {
          "component": "Input module",
          "function": "Receives signals from switches, sensors, buttons, and other field devices."
        },
        {
          "component": "Output module",
          "function": "Sends electrical commands to loads such as indicators, relays, valves, or motors."
        },
        {
          "component": "Memory",
          "function": "Stores the operating system, user program, input and output status, timer values, counters, and other data."
        },
        {
          "component": "Programming interface",
          "function": "Connects a computer or programming device to the PLC for program creation, monitoring, and diagnostics."
        },
        {
          "component": "Communication interface",
          "function": "Allows the PLC to exchange data with other PLCs, human-machine interfaces, sensors, and supervisory systems."
        }
      ],
      "operating_cycle": [
        {
          "stage": 1,
          "name": "Input scan",
          "description": "The PLC reads the current state of each physical input and stores the states in input memory."
        },
        {
          "stage": 2,
          "name": "Program execution",
          "description": "The CPU evaluates program instructions in sequence and updates internal data and output instructions."
        },
        {
          "stage": 3,
          "name": "Output update",
          "description": "The PLC transfers the calculated output states to the physical output modules."
        },
        {
          "stage": 4,
          "name": "Diagnostics and communication",
          "description": "The PLC performs self-diagnostics and handles communication tasks before beginning the next scan."
        }
      ],
      "addressing_example": {
        "input_devices": [
          {
            "symbol": "Start",
            "device": "Normally closed Start push button",
            "address": "%IX0.0",
            "logic_state_when_pressed": "0"
          },
          {
            "symbol": "Stop",
            "device": "Normally open Stop push button",
            "address": "%IX0.1",
            "logic_state_when_pressed": "1"
          },
          {
            "symbol": "ProductSensor",
            "device": "Photoelectric sensor",
            "address": "%IX0.2",
            "logic_state_when_detected": "1"
          }
        ],
        "output_devices": [
          {
            "symbol": "Motor",
            "device": "Motor contactor or virtual motor",
            "address": "%QX0.0",
            "logic_state_when_active": "1"
          },
          {
            "symbol": "GreenLamp",
            "device": "Virtual green lamp",
            "address": "%QX0.1",
            "logic_state_when_active": "1"
          }
        ],
        "note": "Addressing notation varies among PLC manufacturers. The example uses an IEC-style notation for instructional purposes."
      },
      "ladder_logic_basics": [
        {
          "symbol": "Normally open contact",
          "function": "Passes power or a true condition when its referenced bit is 1."
        },
        {
          "symbol": "Normally closed contact",
          "function": "Passes power or a true condition when its referenced bit is 0."
        },
        {
          "symbol": "Coil",
          "function": "Sets or resets the referenced output or internal memory bit when its rung condition is true."
        },
        {
          "symbol": "Connector",
          "function": "Links the output condition of one part of a program to another rung."
        }
      ],
      "boolean_logic_examples": [
        {
          "control_requirement": "A warning lamp activates only when both GuardDoor is closed and EmergencyReset is active.",
          "expression": "WarningLamp = GuardDoor AND EmergencyReset",
          "ladder_interpretation": "Place the GuardDoor and EmergencyReset contacts in series before the warning-lamp coil."
        },
        {
          "control_requirement": "A conveyor motor runs when either Start is pressed or AutoMode is enabled.",
          "expression": "Motor = Start OR AutoMode",
          "ladder_interpretation": "Place the Start and AutoMode branches in parallel before the motor coil."
        },
        {
          "control_requirement": "A machine is not permitted to start while a fault is present.",
          "expression": "MachinePermit = NOT Fault",
          "ladder_interpretation": "Use a normally closed Fault contact as part of the machine-start condition."
        }
      ]
    },
    "classroom_activity_design": [
      {
        "phase": 1,
        "title": "Engagement and prior-knowledge check",
        "time_minutes": 5,
        "teacher_actions": [
          "Show a short conveyor, traffic-light, or water-tank control scenario.",
          "Ask: What decisions must an automated controller make?",
          "Ask: What would happen if the wiring had to be changed?",
          "Review Boolean logic and relay-control concepts."
        ],
        "student_actions": [
          "Identify sensors, switches, outputs, and decision rules.",
          "Complete a three-question readiness check on AND, OR, and NOT logic."
        ],
        "assessment_evidence": "Students list at least two inputs, one output, and one relevant Boolean relationship."
      },
      {
        "phase": 2,
        "title": "PLC concept presentation",
        "time_minutes": 10,
        "teacher_actions": [
          "Define a PLC and show its industrial applications.",
          "Explain the CPU, power supply, I/O modules, memory, programming interface, and communication interface.",
          "Compare a PLC-based circuit with a hardwired relay circuit."
        ],
        "student_actions": [
          "Label a PLC block diagram.",
          "Match each component to its function."
        ],
        "assessment_evidence": "Students complete a component-and-function matching activity."
      },
      {
        "phase": 3,
        "title": "Input, scan, program, and output model",
        "time_minutes": 15,
        "teacher_actions": [
          "Present the four stages of a typical PLC scan cycle.",
          "Display a live status table for several inputs and outputs.",
          "Change one input during execution and ask students to predict the output.",
          "Distinguish physical I/O addresses from internal memory addresses."
        ],
        "student_actions": [
          "Draw the scan-cycle sequence from memory.",
          "Predict output behavior before and after an input changes.",
          "Complete a short input-address and output-address classification exercise."
        ],
        "assessment_evidence": "Students correctly sequence the scan stages and classify six addresses."
      },
      {
        "phase": 4,
        "title": "Ladder logic mini-lesson",
        "time_minutes": 15,
        "teacher_actions": [
          "Explain power rails, rungs, contacts, coils, connectors, addresses, and comments.",
          "Demonstrate series contacts as AND logic and parallel branches as OR logic.",
          "Show the difference between a physical normally closed button and a normally closed PLC contact instruction.",
          "Model two simple programs using the simulator."
        ],
        "student_actions": [
          "Identify normally open and normally closed instructions.",
          "Write Boolean expressions for sample ladder rungs.",
          "Predict the energization of each rung."
        ],
        "assessment_evidence": "Students convert two verbal requirements into correct Boolean expressions."
      },
      {
        "phase": 5,
        "title": "Group design laboratory",
        "time_minutes": 25,
        "activity_title": "Virtual conveyor start and stop control",
        "scenario": "Design a PLC program for a conveyor. The conveyor starts when the Start button is pressed and the Stop button is not pressed. A guard-door contact must be closed for operation. The motor output is represented by a virtual lamp if a physical motor is not used.",
        "assigned_devices": [
          {
            "symbol": "Start",
            "type": "Normally closed Start button",
            "address": "%IX0.0",
            "state_when_pressed": "0"
          },
          {
            "symbol": "Stop",
            "type": "Normally open Stop button",
            "address": "%IX0.1",
            "state_when_pressed": "1"
          },
          {
            "symbol": "GuardDoor",
            "type": "Safety door limit switch",
            "address": "%IX0.2",
            "state_when_closed": "1"
          },
          {
            "symbol": "ConveyorMotor",
            "type": "Virtual conveyor output",
            "address": "%QX0.0",
            "state_when_running": "1"
          }
        ],
        "control_expression": "ConveyorMotor = NOT Start AND NOT Stop AND GuardDoor",
        "group_roles": [
          {
            "role": "Control engineer",
            "responsibility": "Analyze the process and write the control requirement."
          },
          {
            "role": "Programmer",
            "responsibility": "Create the ladder logic and enter addresses."
          },
          {
            "role": "I/O technician",
            "responsibility": "Build or simulate the input and output assignments."
          },
          {
            "role": "Test engineer",
            "responsibility": "Prepare test cases, run the program, and record results."
          }
        ],
        "student_tasks": [
          "Draw an I/O block diagram.",
          "Create an I/O address table.",
          "Write the Boolean control expression.",
          "Develop a ladder logic program.",
          "Test at least six input combinations.",
          "Add comments and descriptive device names.",
          "Compare expected and actual outputs."
        ],
        "minimum_test_cases": [
          {
            "Start": "Not pressed",
            "Stop": "Not pressed",
            "GuardDoor": "Closed",
            "expected_motor": "Off"
          },
          {
            "Start": "Pressed",
            "Stop": "Not pressed",
            "GuardDoor": "Closed",
            "expected_motor": "On"
          },
          {
            "Start": "Pressed",
            "Stop": "Pressed",
            "GuardDoor": "Closed",
            "expected_motor": "Off"
          },
          {
            "Start": "Pressed",
            "Stop": "Not pressed",
            "GuardDoor": "Open",
            "expected_motor": "Off"
          }
        ],
        "teacher_support": [
          "Ask probing questions rather than immediately correcting ladder errors.",
          "Use the four-step method: identify devices, assign addresses, express logic, and test.",
          "Provide a partially completed example if students cannot construct the first rung.",
          "Check each group for electrically and logically safe behavior."
        ],
        "completion_criteria": [
          "The I/O table matches the assigned devices.",
          "All contacts and the coil use valid addresses.",
          "The motor follows the control expression in all test cases.",
          "The program includes comments and device labels.",
          "The group documents its test results."
        ]
      },
      {
        "phase": 6,
        "title": "Challenge and troubleshooting task",
        "time_minutes": 5,
        "teacher_actions": [
          "Introduce a fault such as an incorrect normally open or normally closed Stop contact.",
          "Ask groups to identify the fault from the observed behavior.",
          "Ask them to correct, retest, and document the change."
        ],
        "student_tasks": [
          "Compare observed behavior with expected behavior.",
          "Locate the incorrect instruction.",
          "Correct the program and verify the result."
        ],
        "assessment_evidence": "Students connect a program error to an incorrect output behavior and correct it."
      },
      {
        "phase": 7,
        "title": "Review and exit assessment",
        "time_minutes": 5,
        "teacher_actions": [
          "Review PLC components, scan cycle, addressing, and ladder logic.",
          "Ask students to explain the difference between an input address and an output address.",
          "Ask students to describe how series and parallel contacts represent Boolean logic."
        ],
        "student_tasks": [
          "Complete a five-question exit ticket.",
          "Submit one unanswered reflection question."
        ],
        "assessment_evidence": "Exit-ticket responses demonstrate basic knowledge of PLC structure, operation, and ladder logic."
      }
    ],
    "assessment_plan": {
      "formative_assessment": [
        "Readiness quiz on Boolean logic",
        "Questioning during demonstrations",
        "Component-matching task",
        "Input and output state-prediction exercises",
        "Observation during the group laboratory",
        "Peer review of I/O tables and test cases"
      ],
      "summative_assessment": [
        {
          "task": "Individual ladder interpretation",
          "weight": 20,
          "criteria": [
            "Correctly interprets contacts and coils",
            "Correctly identifies the Boolean logic",
            "Correctly interprets input and output states"
          ]
        },
        {
          "task": "Individual control-design question",
          "weight": 30,
          "criteria": [
            "Correctly identifies inputs and outputs",
            "Assigns plausible addresses",
            "Writes the correct control expression",
            "Draws a valid ladder diagram"
          ]
        },
        {
          "task": "Group PLC laboratory",
          "weight": 35,
          "criteria": [
            "Correct I/O mapping",
            "Correct program operation",
            "Systematic testing",
            "Troubleshooting quality",
            "Documentation and communication"
          ]
        },
        {
          "task": "Exit ticket",
          "weight": 15,
          "criteria": [
            "Understanding of PLC components",
            "Understanding of the scan cycle",
            "Understanding of ladder logic",
            "Understanding of I/O addressing"
          ]
        }
      ],
      "success_standard": "A student meets the lesson objective if the student can design and test a simple PLC logic circuit with at least 80 percent accuracy.",
      "common_rubric_scale": [
        {
          "level": "Excellent",
          "score": "90-100 percent",
          "description": "The design is correct, clearly documented, systematically tested, and independently troubleshooted."
        },
        {
          "level": "Proficient",
          "score": "80-89 percent",
          "description": "The design is functionally correct with minor documentation or testing omissions."
        },
        {
          "level": "Developing",
          "score": "60-79 percent",
          "description": "The design contains several logic or addressing errors but shows partial understanding."
        },
        {
          "level": "Beginning",
          "score": "Below 60 percent",
          "description": "The student needs additional instruction in Boolean logic, addressing, or ladder structure."
        }
      ]
    },
    "homework": {
      "assignment": "Design a two-output PLC system for a traffic-light or package-sorting application.",
      "required_submissions": [
        "Process description",
        "Input and output device list",
        "I/O address table",
        "Boolean expressions for each output",
        "Ladder logic diagrams",
        "A test table with at least eight operating scenarios",
        "A short explanation of how the PLC scan cycle affects operation"
      ]
    },
    "teacher_preparation_checklist": [
      "Open and test the PLC simulator before class.",
      "Prepare both normal and faulty ladder programs.",
      "Verify that virtual sensors and outputs can be changed by students.",
      "Create printable I/O tables and Boolean truth tables.",
      "Review the sample conveyor program for address consistency.",
      "If using hardware, inspect wiring, fuses, power supplies, and emergency-stop provisions.",
      "Prepare an alternative demonstration for students with different levels of prior experience."
    ],
    "sample_board_questions": [
      {
        "question": "What are the three main functional sections of a PLC?",
        "expected_answer": "Input section, processing section or CPU, and output section."
      },
      {
        "question": "Why does a PLC normally repeat its scan cycle?",
        "expected_answer": "It must continuously monitor inputs, execute the control program, and refresh outputs as process conditions change."
      },
      {
        "question": "A normally closed contact is false when which condition exists?",
        "expected_answer": "The contact instruction is false when its referenced bit or input is 1."
      },
      {
        "question": "What logic is represented by two contacts in series?",
        "expected_answer": "AND logic."
      },
      {
        "question": "What logic is represented by two branches in parallel?",
        "expected_answer": "OR logic."
      }
    ],
    "lesson_summary": "PLCs automate control by reading inputs, processing stored logic, and updating outputs in a repeated scan cycle. Understanding PLC components, I/O addressing, the scan cycle, and ladder logic provides the foundation for industrial control programming. Successful students should be able to translate a simple control requirement into an I/O table, Boolean expression, ladder diagram, and tested PLC program."
  }
}

{
  "knowledge_point": "Robotic Process Automation (RPA)",
  "lesson_title": "From Manual Processes to Reliable RPA Bots",
  "target_audience": "Upper-secondary or vocational students with basic information technology skills",
  "suggested_duration_minutes": 90,
  "learning_context": "Students automate a repetitive, rule-based business process such as invoice registration, employee onboarding, or report transfer.",
  "prerequisites": [
    "Basic understanding of files, folders, web forms, and spreadsheets",
    "Basic knowledge of variables, conditions, and loops",
    "Ability to follow a workflow diagram"
  ],
  "teaching_objectives": {
    "knowledge_objectives": [
      "Define Robotic Process Automation and explain its role in digital transformation.",
      "Describe attended, unattended, and hybrid automation models.",
      "Distinguish RPA from manual processing, scripting, and artificial intelligence.",
      "Identify the business value of RPA, including labor savings, accuracy, compliance, and scalability."
    ],
    "skill_objectives": [
      "Analyze a manual process and determine whether it is suitable for RPA.",
      "Create an as-is and to-be process map.",
      "Use an RPA development environment to configure activities, variables, selectors, conditions, and loops.",
      "Implement basic error handling and logging.",
      "Test a bot with normal, boundary, and invalid data.",
      "Calculate basic automation metrics such as time savings and return on investment."
    ],
    "professional_objectives": [
      "Apply security and responsible-use principles when handling credentials and business data.",
      "Document an automation solution and communicate its benefits and limitations.",
      "Recognize that RPA should improve a process rather than automate an unnecessarily complex process."
    ]
  },
  "key_points": [
    {
      "point": "Core concept of RPA",
      "explanation": "RPA software mimics user interactions with applications and systems to execute repetitive, rule-based tasks."
    },
    {
      "point": "Suitable processes",
      "explanation": "Good candidates are stable, repetitive, rule-based, digital, and supported by clear input and output data."
    },
    {
      "point": "RPA operating models",
      "explanation": "Attended automation supports a human, unattended automation runs independently, and hybrid automation combines both approaches."
    },
    {
      "point": "Workflow development",
      "explanation": "Students must understand variables, data types, activities, selectors, control flow, and application integration."
    },
    {
      "point": "Exception handling",
      "explanation": "A reliable bot should identify errors, continue or stop appropriately, record the problem, and support recovery."
    },
    {
      "point": "Testing and validation",
      "explanation": "Testing must include normal cases, boundary values, missing information, invalid input, and application failures."
    },
    {
      "point": "Governance and security",
      "explanation": "Credentials must be protected, access rights should be limited, and sensitive data must be handled according to organizational policy."
    }
  ],
  "common_difficulties": [
    {
      "difficulty": "Selecting an appropriate process for automation",
      "causes": [
        "Ignoring process instability",
        "Failing to consider exceptions",
        "Automating a process without first simplifying it"
      ],
      "teaching_strategy": "Use a process-screening checklist and compare several sample processes through group discussion."
    },
    {
      "difficulty": "Understanding selectors and user-interface elements",
      "causes": [
        "Interface elements are poorly named",
        "Dynamic elements cause elements not to be found",
        "The student confuses an element with a selector"
      ],
      "teaching_strategy": "Demonstrate selector capture, inspect elements interactively, and use stable selector strategies."
    },
    {
      "difficulty": "Handling variable types and data conversion",
      "causes": [
        "Confusing strings and numbers",
        "Ignoring empty or null values",
        "Failing to convert imported spreadsheet values"
      ],
      "teaching_strategy": "Provide a data-type table and require students to inspect values before using them."
    },
    {
      "difficulty": "Debugging failed workflows",
      "causes": [
        "No step-by-step execution information",
        "Insufficient screenshots and logs",
        "Errors are hidden inside repeated activities"
      ],
      "teaching_strategy": "Teach students to run workflows one step at a time, review error screenshots, add logs, and isolate the failing activity."
    },
    {
      "difficulty": "Designing exception handling",
      "causes": [
        "Assuming every record is valid",
        "Using one generic error message",
        "Terminating the entire process for a recoverable record"
      ],
      "teaching_strategy": "Classify exceptions as business, validation, or technical exceptions and route them to different handling paths."
    }
  ],
  "teaching_preparation": {
    "teacher_resources": [
      "RPA introduction slides",
      "As-is and to-be process-map templates",
      "RPA process-screening checklist",
      "Demonstration bot and completed reference workflow",
      "Sample invoice CSV files containing valid, missing, and invalid data",
      "Mock accounting or web form system",
      "Grading rubric"
    ],
    "student_resources": [
      "RPA development environment such as UiPath Studio, Automation Anywhere, Blue Prism, or Power Automate Desktop",
      "Practice data set",
      "Workflow design worksheet",
      "Bot testing log"
    ],
    "environment_requirements": [
