        "correction": "Higher gains can improve speed or accuracy but can also produce oscillation, noise amplification, and actuator saturation."
      },
      {
        "misconception": "The integral term makes the system faster.",
        "correction": "The integral term removes accumulated error, but excessive integral action commonly increases overshoot and settling time."
      },
      {
        "misconception": "The derivative term corrects the destination of the setpoint.",
        "correction": "The derivative term responds to the rate of change of error and primarily adds damping."
      },
      {
        "misconception": "Once the error becomes zero, the integral term becomes irrelevant.",
        "correction": "At zero error the integral contribution stops changing, but its accumulated value can remain and continue affecting the output."
      },
      {
        "misconception": "Derivative action is always desirable.",
        "correction": "Derivative action can amplify high-frequency measurement noise and should usually be filtered."
      }
    ],
    "teaching_resources": [
      "Interactive PID simulator or spreadsheet model",
      "DC motor or first-order plant simulation",
      "Projector or shared display",
      "Graphing tool for plotting reference and output",
      "PID parameter worksheet",
      "Optional noise generator and actuator-limit model"
    ],
    "safety_and_classroom_management": [
      "Use simulations by default rather than connecting student controllers directly to mains-powered equipment.",
      "If a physical motor or heater is used, include an emergency stop, current or temperature limits, insulated connections, and teacher supervision.",
      "Assign clear group roles to ensure that all students participate.",
      "Provide a baseline controller so students can compare changes rather than begin with an unstable model."
    ],
    "extension_tasks": [
      "Compare derivative action on error with derivative action on measurement.",
      "Add derivative filtering and measure its effect on noise.",
      "Implement conditional integration or back-calculation anti-windup.",
      "Tune two different plants and explain why the same PID settings are not equally effective.",
      "Explore proportional-only control when exact steady-state tracking is not required."
    ],
    "teacher_reflection_questions": [
      "Can students distinguish a parameter's mathematical role from its observed system effect?",
      "Can they explain why a controller must be tested under disturbances and actuator constraints?",
      "Can they diagnose oscillation using more than trial and error?",
      "Can they connect continuous PID equations to a sampled implementation?",
      "Did the activity help students understand the trade-offs involved in control performance rather than only memorizing formulas?"
    ]
  }
}

