{
  "title": "Reinforcement Learning for Industrial Automation",
  "knowledge_point": {
    "name": "Reinforcement Learning for Industrial Automation",
    "category": "Intelligent Control and Automation",
    "lesson_type": "Theory, discussion, and simulation-based activity",
    "suggested_duration_minutes": 90,
    "target_audience": "Undergraduate students in automation, electrical engineering, mechanical engineering, robotics, or industrial informatics",
    "prerequisites": [
      "Basic control-system concepts",
      "Feedback control and PID control",
      "Probability and basic statistics",
      "Basic Python or simulation-tool skills"
    ]
  },
  "teaching_objectives": {
    "knowledge_objectives": [
      "Explain the basic structure of a reinforcement learning system: agent, environment, state, action, reward, and policy.",
      "Describe how an industrial control problem can be formulated as a Markov Decision Process or a constrained Markov Decision Process.",
      "Compare supervised learning, reinforcement learning, and classical industrial control.",
      "Explain the main ideas of value functions, policies, Q-learning, and actor-critic methods.",
      "Identify common industrial applications of reinforcement learning, including robotics, process control, energy optimization, production scheduling, and predictive maintenance."
    ],
    "skill_objectives": [
      "Design a meaningful state representation, action space, and reward function for a simple automation task.",
      "Implement or interpret a small Q-learning agent in a simulated environment.",
      "Evaluate an RL controller using safety, performance, energy, and robustness indicators rather than reward alone.",
      "Compare an RL controller with a conventional controller such as a PID controller."
    ],
    "application_and_attitude_objectives": [
      "Recognize that reinforcement learning should complement, rather than automatically replace, established industrial control methods.",
      "Understand the importance of safety constraints, simulation, human supervision, and responsible deployment.",
      "Analyze how reward design can lead to undesirable behavior or reward hacking.",
      "Appreciate the need for reliable communication between learning algorithms and industrial automation systems."
    ]
  },
  "key_points": [
    {
      "topic": "Reinforcement learning in closed-loop control",
      "explanation": "An agent observes the process state, selects an action, receives feedback from the environment, and learns a policy that maximizes long-term cumulative reward.",
      "industrial_connection": "The agent can represent a controller, robot, scheduler, or energy-management system, while the environment represents a machine, production line, or physical process."
    },
    {
      "topic": "Markov Decision Process",
      "explanation": "An MDP is commonly described by the state space S, action space A, transition model P, reward function R, and discount factor gamma.",
      "industrial_connection": "The transition model represents how a physical process changes after an action. If the process is only partially observable, a POMDP or belief-state representation may be required."
    },
    {
      "topic": "State, action, and reward design",
      "explanation": "State variables should contain enough information for decision-making. Actions should be physically executable. Rewards should reflect productivity, quality, energy, wear, and safety objectives.",
      "industrial_connection": "Poor state or reward design can produce unstable control, excessive energy consumption, premature equipment failure, or unsafe behavior."
    },
    {
      "topic": "Policies and value functions",
      "explanation": "A policy determines which action is selected in each state. A value function estimates the expected future return. Q-learning estimates the value of taking an action and then following an optimal policy.",
      "industrial_connection": "The learned policy can generate control commands, setpoints, speed references, robot trajectories, or production decisions."
    },
    {
