  "Teaching Material": {
    "general_information": {
      "knowledge_point": "Robust Control in Automated Systems",
      "lesson_title": "Robust Control for Automated Systems: Stable Performance Under Uncertainty",
      "target_audience": "Advanced undergraduate or graduate students in control engineering, automation, robotics, mechatronics, or electrical engineering",
      "duration_minutes": 180,
      "class_size": "20–40 students",
      "prerequisites": [
