    "core_teaching_notes": {
      "essential_definitions": [
        {
          "term": "Nominal model",
          "definition": "A selected plant model P₀(s) used as the center of the uncertainty description."
        },
        {
          "term": "Robust stability",
          "definition": "Internal stability of the closed-loop system for every admissible stable uncertainty Δ satisfying a specified bound such as ||Δ||∞ ≤ 1."
        },
        {
          "term": "Robust performance",
          "definition": "Satisfaction of stability and performance requirements throughout the uncertainty set, rather than only at P₀(s)."
        },
        {
          "term": "Internal stability",
          "definition": "All relevant internal closed-loop transfer functions are stable, with no unstable pole hidden by cancellation or an unobservable internal mode."
        },
        {
          "term": "Uncertainty structure",
          "definition": "Information about the number, type, location, dependence, and size of uncertain factors."
        }
      ],
      "uncertainty_sources": [
        {
          "source": "Parametric uncertainty",
          "example": "Unknown motor gain K or mechanical time constant τ",
          "typical_effect": "Changes loop gain, bandwidth, damping, and stability margin."
        },
        {
          "source": "Unmodeled dynamics",
          "example": "Flexible modes omitted from a rigid-body model",
          "typical_effect": "Creates phase loss near crossover and possible instability."
        },
        {
          "source": "Time-delay uncertainty",
          "example": "Variable computation, communication, or transport delay",
          "typical_effect": "Adds negative phase and reduces damping."
        },
        {
          "source": "External disturbance",
          "example": "Load torque, wind, or process-variable disturbance",
          "typical_effect": "Produces tracking error and output deviation."
        },
        {
          "source": "Measurement noise and quantization",
          "example": "Noisy position sensor or low-resolution encoder",
          "typical_effect": "Is amplified when loop bandwidth is too high."
        },
        {
          "source": "Nonlinearities and constraints",
          "example": "Actuator saturation, friction, dead zone, or rate limit",
          "typical_effect": "Can invalidate linear robustness guarantees and cause integrator windup."
        }
      ],
      "sensitivity_functions": [
        {
          "function": "S(s) = 1/(1 + PC)",
          "interpretation": "Measures sensitivity of the closed loop to output disturbances and small model perturbations."
        },
        {
          "function": "T(s) = PC/(1 + PC)",
          "interpretation": "Measures reference tracking and transmission of measurement noise to the output."
        },
        {
          "function": "C(s)S(s)",
          "interpretation": "Represents control effort caused by a reference command."
        },
        {
          "function": "M_s = maxω |S(jω)|",
          "interpretation": "A common sensitivity-peak indicator; a large value usually indicates strong disturbance amplification and proximity to instability."
        }
      ],
      "robust_control_methods": [
        {
          "method": "Robust PID and loop shaping",
          "suitable_when": "The plant is relatively simple and uncertainty is mainly gain, pole, or moderate delay variation.",
          "strengths": "Simple, transparent, easy to implement, and widely accepted in industry.",
          "limitations": "May require conservative retuning and can struggle with many coupled uncertainties."
        },
        {
          "method": "H∞ mixed-sensitivity design",
          "suitable_when": "Frequency-dependent tracking, disturbance, noise, and control-effort requirements must be balanced.",
          "strengths": "Provides a systematic worst-case design and directly supports weighted performance specifications.",
          "limitations": "Weight selection and model reduction require engineering judgment; the resulting controller may be conservative or higher order."
        },
        {
          "method": "μ-synthesis",
          "suitable_when": "Uncertainties have known structure, repeated blocks, or multiple locations.",
          "strengths": "Can analyze robust stability and robust performance for structured uncertainty.",
          "limitations": "Computationally demanding and may require simplified models or uncertain-structure approximations."
        },
        {
          "method": "Sliding-mode control",
          "suitable_when": "Uncertainty or disturbance is sufficiently matched and a discontinuous or boundary-layer control law is acceptable.",
          "strengths": "Can provide strong disturbance rejection and finite-time convergence.",
          "limitations": "Chattering, sampling effects, actuator wear, and noise sensitivity require careful treatment."
        },
        {
          "method": "Robust model predictive control",
          "suitable_when": "State or output predictions, operating constraints, and operational optimization are important.",
          "strengths": "Can explicitly handle constraints and operating scenarios.",
          "limitations": "Greater computational and modeling demands; real-time feasibility must be checked."
        },
        {
          "method": "Adaptive control",
          "suitable_when": "Parameters change over time and can be estimated safely during operation.",
          "strengths": "Can improve performance near the current operating point.",
          "limitations": "Robustness depends on excitation, estimation, parameter convergence, and implementation safeguards; adaptivity is not automatically fail-safe."
        }
      ],
      "h_infinity_design": {
        "core_interpretation": "For a stable SISO transfer function G, ||G||∞ = maxω |G(jω)|. In MIMO systems, the maximum singular value is used. It represents the largest amplification of an energy-limited input.",
        "standard_mixed_sensitivity_objective": "Minimize ||[W_e S; W_u C S; W_m T]||∞",
        "weight_interpretation": [
          "W_e is made large in frequency ranges where tracking errors or output disturbances must be strongly attenuated.",
          "W_u limits control effort and protects actuators.",
          "W_m can emphasize model-uncertainty sensitivity, usually associated with complementary sensitivity in suitable SISO uncertainty descriptions.",
          "Weights are design requirements, not arbitrary numbers; changing them changes the desired robustness-performance tradeoff."
        ],
        "small_gain_connection": "For a common SISO multiplicative plant uncertainty P = P₀(1 + WΔ), nominal internal stability together with ||W T||∞ < 1 is a sufficient robust-stability condition.",
        "structured_connection": "A standard robust-stability test is supω μ_Δ(M(jω)) < 1, where M is the nominal closed-loop transfer matrix associated with the structured uncertainty and μ is the structured singular value."
      },
      "standard_design_workflow": [
        "Define the control objective and unacceptable outcomes.",
        "Determine operating conditions and uncertainty sources.",
        "Assign quantitative uncertainty bounds and identify their structure.",
        "Choose a nominal model and calculate baseline stability and performance.",
        "Translate performance objectives into frequency weights or other constraints.",
        "Select a synthesis method consistent with plant complexity and uncertainty structure.",
        "Analyze robust stability and robust performance.",
        "Test nominal, boundary, combined, disturbance, and noise scenarios.",
        "Include nonlinearities, saturation, sampling, and implementation limitations.",
        "Document assumptions, results, failure modes, and the final controller."
      ],
      "common_misconceptions": [
        {
          "misconception": "If the nominal closed loop is stable, the controller is robust.",
          "correction": "Nominal stability is only one point in the model family; uncertainty analysis is still required."
        },
        {
          "misconception": "Passing many Monte Carlo simulations proves robustness.",
          "correction": "Monte Carlo testing samples the uncertainty set and supplements, but does not replace, analytical or numerical robust-stability certification."
        },
        {
          "misconception": "Increasing controller gain always improves control.",
          "correction": "Higher gain may improve low-frequency rejection but can increase noise amplification, actuator effort, excitation of flexible modes, and loss of stability margin."
        },
        {
          "misconception": "H∞ control is always better than PID or H2 control.",
          "correction": "The appropriate method depends on uncertainty, constraints, computational resources, model quality, and performance priorities."
        },
        {
          "misconception": "H∞ and H2 describe the same objective.",
          "correction": "H∞ emphasizes worst-case deterministic amplification, while H2 commonly describes expected RMS behavior under stochastic or energy-based assumptions."
        },
        {
          "misconception": "A robust controller must have the best nominal response.",
          "correction": "A robust controller may deliberately sacrifice nominal performance to obtain acceptable worst-case performance."
        }
      ]
