  "key_terms": [
    {
      "term": "Broodstock",
      "definition": "Mature aquatic organisms selected and maintained as parents for reproduction."
    },
    {
      "term": "Phenotype",
      "definition": "The observable performance or appearance of an organism, such as growth, survival, or disease resistance."
    },
    {
      "term": "Genotype",
      "definition": "The genetic makeup of an organism, which may influence its phenotype."
    },
    {
      "term": "Heritability",
      "definition": "The degree to which variation in a trait in a particular population and environment is associated with genetic variation."
    },
    {
      "term": "Feed conversion ratio",
      "definition": "The amount of feed required to produce a given amount of weight gain; lower values are generally better."
    },
    {
      "term": "Selection index",
      "definition": "A weighted score that combines several traits into one decision aid."
    },
    {
      "term": "Inbreeding",
      "definition": "Mating between genetically related individuals, which can reduce fertility, vigor, and adaptability."
    },
    {
      "term": "Genetic diversity",
      "definition": "The variety of genetic information within a farmed or wild population; it supports adaptation and long-term resilience."
    },
    {
      "term": "Mass selection",
      "definition": "Selecting individual parents according to their own measured performance."
    },
    {
      "term": "Family-based selection",
      "definition": "Using the performance of families, siblings, or offspring to help make selection decisions and reduce the influence of individual environmental differences."
    }
  ],
