  "classroom_activity_design": [
    {
      "sequence": 1,
      "phase": "Entry diagnostic and system mental model",
      "time_minutes": 10,
      "teacher_actions": [
        "Display a short RAS image, process sketch, or simulated dashboard showing temperature, dissolved oxygen, TAN, flow, and filter pressure.",
        "Ask: What is happening, what is uncertain, and what should be checked first?",
        "Do not reveal the intended diagnosis immediately."
      ],
      "student_actions": [
        "Individually list at least five system inputs, five outputs, and three possible failures.",
        "Pair with another learner and mark assumptions, unknowns, and risk-critical observations."
      ],
      "deliverable": "Initial process sketch and list of information gaps",
      "formative_check": "Use the responses to identify misconceptions about flow, oxygen, ammonia, and alarms."
    },
    {
      "sequence": 2,
      "phase": "Process-train jigsaw",
      "time_minutes": 20,
      "teacher_actions": [
        "Assign each group a subsystem: solids, biofilter, oxygen and carbon dioxide, temperature, disinfection, or controls.",
        "Provide a blank process flow diagram and a subsystem design prompt.",
        "Ask each group to identify one design variable, one measurement, one failure mode, and one maintenance task."
      ],
      "student_actions": [
        "Complete the assigned subsystem section of the process flow diagram.",
        "Explain the subsystem to another group in a one-minute mini-presentation.",
        "Connect the subsystem to upstream and downstream requirements."
      ],
      "deliverable": "Annotated integrated process flow diagram",
      "formative_check": "Assess whether groups can distinguish solids, dissolved contaminants, gas transfer, heat, and control functions."
    },
    {
      "sequence": 3,
      "phase": "Mass-balance clinic",
      "time_minutes": 25,
      "teacher_actions": [
        "Demonstrate unit conversion and the difference between a flow rate, hydraulic exchange time, and treatment contact time.",
        "Work one water-balance example and one TAN-loading example on the board.",
        "Emphasize peak load, uncertainties, and the need to state source assumptions."
      ],
      "student_actions": [
        "Calculate the nominal flow for the case system.",
        "Construct a water-balance table using the supplied loss values or identify which values are missing.",
        "Calculate average feed load and define how a peak feed case would be established.",
        "Check units and write a short interpretation of the dominant load."
      ],
      "deliverable": "One-page hydraulic and mass-balance worksheet",
      "formative_check": "Give immediate feedback on dimensional consistency, peak-load reasoning, and assumptions."
    },
    {
      "sequence": 4,
      "phase": "Integrated preliminary design studio",
      "time_minutes": 50,
      "teacher_actions": [
        "Assign team roles: process design, water quality and biofiltration, controls and reliability, and operations and sustainability.",
