      "student_actions": [
        "Develop the design basis and process flow diagram.",
        "Select and preliminarily size major unit processes.",
        "Define sensors, actuators, alarms, interlocks, redundancy, and emergency actions.",
        "Prepare an operations, maintenance, biosecurity, and sustainability outline."
      ],
      "deliverable": "Draft preliminary RAS design package",
      "formative_check": "Use a checklist covering units, assumptions, safety, redundancy, and species-specific targets."
    },
    {
      "sequence": 5,
      "phase": "Break and informal system review",
      "time_minutes": 10,
      "teacher_actions": [
        "Display the process train and invite learners to annotate questions or points requiring clarification."
      ],
      "student_actions": [
        "Review the draft design and identify one missing assumption, one possible bottleneck, and one safety concern."
      ],
      "deliverable": "Questions for the next checkpoint",
      "formative_check": "Use questions to adjust emphasis before the control and troubleshooting sessions."
    },
    {
      "sequence": 6,
      "phase": "Control philosophy and management planning",
      "time_minutes": 20,
      "teacher_actions": [
        "Demonstrate how to convert a water-quality target into a control loop.",
        "Explain the difference between an alarm, an interlock, an automatic action, and a manual operating instruction.",
        "Provide a partial control matrix and emergency-card template."
      ],
      "student_actions": [
        "Complete a matrix with variable, sensor, setpoint, alarm, actuator, automatic response, manual fallback, and calibration frequency.",
        "Write a startup sequence and a daily operating checklist.",
        "Define safe states for loss of power, low oxygen, pump failure, and high temperature."
