    {
      "sequence": 7,
      "phase": "Failure-mode tabletop simulation",
      "time_minutes": 20,
      "teacher_actions": [
        "Distribute scenario cards to teams.",
        "Give each team five minutes to develop a response and two minutes to report.",
        "Require teams to distinguish an immediate protective action from a later root-cause investigation."
      ],
      "student_actions": [
        "Follow the sequence detect, verify, isolate, mitigate, communicate, recover, and document.",
        "State which measurements are needed, which equipment should be stopped or bypassed, and who must be notified.",
        "Propose a recovery test before returning to normal production."
