      "term": "Player",
      "definition": "A decision-maker in a game, such as a firm or consumer."
    },
    {
      "term": "Strategy",
      "definition": "A complete plan or available action that specifies what a player will do in a situation."
    },
    {
      "term": "Payoff",
      "definition": "The utility, profit, revenue, cost, or other outcome that a player values."
    },
    {
      "term": "Best response",
      "definition": "The strategy that gives a player the highest payoff given the other player's strategy."
    },
    {
      "term": "Dominant strategy",
      "definition": "A strategy that is optimal regardless of the strategy chosen by the other player."
    },
    {
      "term": "Nash equilibrium",
      "definition": "A combination of strategies in which no player can improve its payoff by changing its strategy alone."
    },
    {
      "term": "Simultaneous game",
      "definition": "A game in which players choose strategies without observing the other player's current choice."
    },
    {
      "term": "Sequential game",
      "definition": "A game in which at least one player chooses after observing an earlier decision."
    },
    {
      "term": "Backward induction",
      "definition": "A solution method for sequential games that begins with the last decision and works backward."
    },
    {
      "term": "Strategic interdependence",
      "definition": "The condition in which one firm's choices affect and are affected by the choices of other firms."
    }
  ],
