  "core_teaching_content": {
    "behavioral_economics": [
      {
        "concept": "Bounded rationality",
        "core_idea": "Decision-makers have limited attention, information, time, and computational capacity.",
        "market_relevance": "Investors may process only some information, use rules of thumb, or trade before all relevant information is incorporated into prices."
