      },
      {
        "concept": "Reference dependence and prospect theory",
        "core_idea": "Outcomes are evaluated relative to a reference point. The value function is generally concave in gains, convex in losses, and steeper for losses.",
        "market_relevance": "Reference points can explain reluctance to realize losses, willingness to hold risky positions after losses, and different reactions to equivalent gains and losses."
      },
      {
        "concept": "Probability weighting",
        "core_idea": "People do not always assess small and medium probabilities according to objective probability.",
        "market_relevance": "Rare events may be overweighted, while moderate risks may be neglected. This can affect insurance, trading, and responses to financial news."
      },
      {
        "concept": "Present bias",
        "core_idea": "Immediate rewards and costs receive disproportionate weight relative to future consequences.",
        "market_relevance": "Present bias can contribute to excessive trading, procrastination, debt, short-termism, and failure to rebalance."
      },
      {
        "concept": "Risk and ambiguity",
        "core_idea": "People may prefer known risks to unknown risks, and risk preferences can change depending on whether they are in a gain or loss domain.",
        "market_relevance": "Uncertainty about earnings, liquidity, or financial institutions can produce ambiguity aversion and delayed decisions."
      },
      {
        "concept": "Social and cognitive influences",
