        {
          "Term": "Mixed strategy",
          "Definition": "A probability distribution over pure strategies. If the probabilities are p1, p2, ..., pm, then each probability is nonnegative and the probabilities sum to one."
        },
        {
          "Term": "Expected payoff",
          "Definition": "The probability-weighted average payoff across all possible outcomes."
        },
        {
          "Term": "Best response",
          "Definition": "A strategy that gives a player the highest attainable payoff given the other player's strategy."
        },
        {
          "Term": "Support",
          "Definition": "The set of pure strategies to which a mixed strategy assigns positive probability."
        },
        {
          "Term": "Mixed-strategy Nash equilibrium",
          "Definition": "A Nash equilibrium in which at least one player uses positive probabilities for more than one pure strategy. A pure equilibrium can also be represented as a degenerate mixed strategy."
