      {
        "term": "Uncertainty",
        "definition": "A decision situation in which probabilities, outcomes, or relevant information are not fully known."
      },
      {
        "term": "Ambiguity",
        "definition": "Uncertainty in which the information can be interpreted in several plausible ways and no agreed probability is available."
      },
      {
        "term": "Expected value",
        "definition": "The probability-weighted average of all possible outcomes."
      },
      {
        "term": "Utility",
        "definition": "A representation of the subjective value or desirability of an outcome."
      },
      {
        "term": "Expected utility",
        "definition": "A decision rule that sums the utilities of outcomes weighted by their probabilities."
      },
      {
        "term": "Risk aversion",
        "definition": "A preference for a certain outcome over a gamble with the same expected value, often modeled with a concave utility function."
      },
      {
        "term": "Risk seeking",
        "definition": "A preference for a gamble over a safer or certain alternative with a comparable expected value, often modeled with a convex utility function."
      },
      {
        "term": "Reference point",
        "definition": "The point against which an outcome is evaluated, such as the status quo, current wealth, or an expected outcome."
      },
      {
        "term": "Loss aversion",
        "definition": "The tendency for losses to feel more significant than equivalent gains."
      },
      {
        "term": "Diminishing sensitivity",
        "definition": "The tendency for the subjective impact of additional gains or losses to decrease as the amount becomes larger."
      },
      {
        "term": "Probability weighting",
        "definition": "The tendency to transform objective probabilities when judging likelihood, such as overweighting small probabilities."
      },
      {
        "term": "Framing effect",
        "definition": "The influence of how the same choice is described on the decision made."
      },
      {
        "term": "Ambiguity aversion",
        "definition": "A preference for a known risk over an unknown or ambiguously described risk."
      },
      {
        "term": "Base-rate neglect",
        "definition": "Insufficient use of population prevalence when evaluating a specific case or test result."
      },
      {
        "term": "Sunk-cost effect",
        "definition": "The tendency to continue an activity because of resources already invested, even when future benefits do not justify continuation."
      },
      {
        "term": "Choice architecture",
        "definition": "The design of the environment in which choices are presented and made."
