      "Voter 2: B > C > A",
      "Voter 3: C > A > B"
    ],
    "majority_cycle": [
      "A defeats B by a 2-to-1 majority.",
      "B defeats C by a 2-to-1 majority.",
      "C defeats A by a 2-to-1 majority."
    ]
  },
  "classroom_activity_design": {
    "opening": {
      "activity": "Warm-up: Majority-cycle challenge",
      "time_minutes": 10,
      "instructions": [
        "Present the three-voter profile A > B > C; B > C > A; C > A > B.",
        "Ask students to determine the majority winner for each pair.",
        "Ask how the group can identify one overall winner if the pairwise results conflict."
      ],
      "expected_discovery": [
        "A beats B.",
        "B beats C.",
        "C beats A.",
        "The majority relation is cyclic, so the pairwise results cannot be represented by a complete and transitive ranking."
      ],
      "teacher_questions": [
        "Is there a candidate who defeats both opponents?",
        "What additional information would be needed to produce a stable overall ranking?",
        "Does the cycle show that voters are irrational?"
      ]
    },
    "concept_building": {
      "activity": "Build the conditions together",
      "time_minutes": 20,
      "instructions": [
        "Introduce the social welfare function.",
        "Define completeness, transitivity, and asymmetry.",
        "Have students infer why unanimity or Pareto efficiency is attractive.",
        "Introduce IIA with a change to a third alternative.",
        "Contrast non-dictatorship with simple one-person-one-vote equality."
      ],
      "mini_check": "Ask students to decide whether each of the following is a description of Pareto, IIA, or non-dictatorship: unanimous support, changing C cannot affect the A-versus-B comparison, and no fixed voter controls every outcome."
    },
    "group_analysis": {
      "activity": "Which assumption would you relax?",
      "time_minutes": 25,
      "group_size": "3 to 4 students",
      "task": "Each group receives one rule: pairwise majority rule, dictatorship, Borda count, plurality rule, or a limited-domain committee rule. Groups must identify the assumptions it satisfies and the assumptions it appears to violate or restrict.",
      "rules": [
        {
          "rule": "Pairwise majority rule",
          "analysis_focus": "It is non-dictatorial and Pareto-respecting for pairwise decisions, but its majority relation can be cyclic and may not define a single transitive social welfare function."
        },
        {
          "rule": "Dictatorship",
          "analysis_focus": "It can produce a complete and transitive ordering and respect unanimity, but it violates non-dictatorship."
        },
        {
          "rule": "Borda count",
          "analysis_focus": "It produces a complete ranking, but it generally uses information about positions of alternatives rather than only each pair separately, so it does not satisfy IIA."
        },
        {
          "rule": "Plurality rule",
          "analysis_focus": "It produces a clear winner in many elections, but it ignores relevant preference information and does not guarantee the same result as a complete social welfare function based only on pairwise majority relations."
        },
        {
          "rule": "Limited-domain committee rule",
          "analysis_focus": "It may be consistent when the domain is restricted, but the restriction itself limits the theorem's universality."
        }
      ],
      "required_output": [
        "One sentence stating the rule's main strength.",
        "One sentence identifying the main problem or condition relaxed.",
        "One real-world example.",
        "One question the group still has."
      ],
      "sharing_and_feedback": "Each group gives a two-minute presentation. The class records the rule, likely condition affected, and institutional lesson in a shared table."
    },
    "proof_intuition": {
      "activity": "Decisive-coalition puzzle",
      "time_minutes": 20,
      "instructions": [
        "Explain that a coalition is decisive for a pair when its members agree on that pair and its view determines the social outcome.",
        "Show that, under IIA, a strict majority is decisive for each pairwise comparison.",
        "Construct two coalitions: one with a two-person majority supporting A over B and another with a different two-person majority supporting B over A.",
        "Ask students why coalitions that are decisive separately can conflict when all three alternatives are considered.",
        "Connect this conflict to the cycle A > B, B > C, and C > A and to the impossibility of satisfying all Arrow conditions."
      ],
      "instructor_note": "A complete proof requires additional formal steps. For an introductory class, emphasize the decisive-majority mechanism and the structural contradiction rather than reproducing every lemma."
    },
    "synthesis": {
      "activity": "Condition trade-off board",
      "time_minutes": 10,
      "instructions": [
        "Write the four conditions on the board: universal domain, Pareto efficiency, IIA, and non-dictatorship.",
        "Add the output requirement: a complete and transitive social ordering.",
        "Ask: 'What problem is created if any one condition is dropped?'",
        "Have students classify responses as logical, institutional, or normative."
      ],
      "conclusion": "Arrow's theorem forces institutional designers to choose which values and logical properties they are willing to trade off."
    },
    "closing": {
      "activity": "Exit ticket",
      "time_minutes": 5,
      "questions": [
        "State Arrow's theorem in no more than two sentences.",
        "Why does the example A beats B, B beats C, C beats A threaten majority rule?",
        "Give one example of relaxing an assumption to avoid the impossibility."
      ]
    }
  },
  "assessment": {
    "formative": [
      "Ask students to classify examples as Pareto, IIA, or non-dictatorship.",
      "Have groups construct a majority cycle.",
      "Use quick polls to compare possible social rankings with unanimity and majority results.",
