      },
      {
        "criterion": "Understanding of assumptions",
        "weight_percent": 25,
        "standard": "Accurately defines all four substantive conditions and gives valid examples."
      },
      {
        "criterion": "Application and analysis",
        "weight_percent": 25,
        "standard": "Correctly analyzes a voting rule or preference profile and identifies which condition is weakened or violated."
      },
      {
        "criterion": "Interpretation and reasoning",
        "weight_percent": 20,
        "standard": "Avoids common misconceptions and explains the theorem's limits and practical implications."
      }
    ],
    "suggested_homework": [
      {
        "task": "Profile construction",
        "instructions": "Create a preference profile for five voters and three alternatives that produces a majority cycle. Show every pairwise majority and explain why no complete, transitive majority ranking is possible."
