      }
    ]
  },
  "teaching_resources": {
    "visual_aids": [
      "A three-alternative preference-ranking diagram.",
      "A directed graph showing A → B → C → A for pairwise majority victories.",
      "A four-condition wall chart for universal domain, Pareto, IIA, and non-dictatorship.",
