{
  "title": "Theories of Learning",
  "teaching_material_type": "Lesson plan, teaching notes, and classroom activities",
  "target_audience": "Introductory teacher-education or educational-psychology students",
  "lesson_overview": {
    "duration": "90 minutes, or two 45-minute sessions",
    "central_question": "How do different theories of learning change the way we interpret learning, design instruction, and assess student progress?",
    "big_idea": "Learning theories are lenses for understanding learning. No single theory explains every learner or every situation, so effective teaching requires evidence, contextual awareness, and thoughtful integration.",
    "working_definition": "Learning is a relatively enduring change in knowledge, skill, attitude, or behavior that results from experience and is supported by evidence such as performance, explanation, retention, or transfer.",
    "scope_note": "This lesson introduces six major learning theories: behaviorism, cognitivism, constructivism, social learning theory, humanistic learning, and connectivism. The list is representative rather than exhaustive."
  },
  "teaching_objectives": {
    "overall_objective": "Students will be able to explain major theories of learning, compare their assumptions and classroom implications, and apply them appropriately to educational situations.",
    "specific_objectives": [
      {
        "objective": "Define learning and distinguish a learning theory from an instructional approach or method.",
        "evidence_of_learning": "Students correctly use terms such as theory, approach, method, mechanism, and evidence in written or oral responses."
      },
      {
        "objective": "Explain the central assumptions, mechanisms, teacher roles, learner roles, strengths, and limitations of major learning theories.",
        "evidence_of_learning": "Students complete a comparison matrix and accurately explain their assigned theory to peers."
      },
      {
        "objective": "Analyze classroom cases by identifying evidence of learning and selecting one or more theories that provide a justified explanation.",
        "evidence_of_learning": "Students refer to specific learner behaviors or products rather than relying only on personal opinion."
      },
      {
        "objective": "Design a learning activity in which instructional decisions are aligned with an explicitly stated theory or theories.",
        "evidence_of_learning": "Students produce a lesson or activity plan that includes goals, learner tasks, teacher support, feedback, assessment, and a discussion of limitations."
      },
      {
        "objective": "Recognize the importance of learner diversity, context, culture, access, and equity when applying learning theories.",
        "evidence_of_learning": "Students identify at least one potential limitation or equity concern in a proposed teaching design."
      }
    ]
  },
  "key_concepts_and_vocabulary": [
    {
      "term": "Learning theory",
      "definition": "A systematic explanation of how learning occurs and what influences it."
    },
    {
      "term": "Learning mechanism",
      "definition": "The process or explanation proposed by a theory, such as reinforcement, encoding, modeling, or knowledge construction."
    },
    {
      "term": "Behaviorism",
      "definition": "A perspective emphasizing observable behavior, environmental conditions, practice, reinforcement, and feedback."
    },
    {
      "term": "Cognitivism",
      "definition": "A perspective emphasizing mental processes such as attention, memory, comprehension, encoding, retrieval, and metacognition."
    },
    {
      "term": "Constructivism",
      "definition": "A perspective emphasizing the active construction of knowledge through prior experience, problem solving, reflection, and social interaction."
    },
    {
      "term": "Social learning theory",
      "definition": "A perspective emphasizing observation, modeling, imitation, social context, self-efficacy, and reciprocal interaction between individuals and environment."
    },
    {
      "term": "Humanistic learning",
      "definition": "A perspective emphasizing the whole person, autonomy, motivation, personal growth, meaning, and self-directed learning."
    },
    {
      "term": "Connectivism",
      "definition": "A perspective emphasizing learning through access to information, participation in networks, collaboration, and the ability to form connections in digital environments."
    },
    {
      "term": "Transfer",
      "definition": "The application of knowledge or skills learned in one context to a new context."
    },
    {
      "term": "Metacognition",
      "definition": "Knowledge and skills that enable learners to plan, monitor, and evaluate their own learning."
    },
