        "term": "Excess demand",
        "definition": "The amount by which desired purchases exceed available supply at a given price vector."
      },
      {
        "term": "Walras' law",
        "definition": "The identity that the price-weighted value of aggregate excess demand is zero."
      },
      {
        "term": "Pareto efficiency",
        "definition": "The absence of any feasible change that benefits at least one person without harming anyone else."
      },
      {
        "term": "Supporting prices",
        "definition": "Prices that make a given allocation optimal for consumers and producers."
      },
      {
        "term": "Social welfare function",
        "definition": "A rule that ranks utility profiles according to a social objective."
      },
