    "common_misconceptions_and_corrections": [
      {
        "misconception": "General equilibrium simply means that all prices are considered at once.",
        "correction": "The defining feature is that all relevant agents optimize and all relevant product and factor markets clear jointly."
      },
      {
        "misconception": "Every market equilibrium is socially optimal.",
        "correction": "A competitive equilibrium is Pareto efficient only under the assumptions of the first welfare theorem."
      },
      {
        "misconception": "Pareto efficiency means that everyone receives the same allocation.",
        "correction": "Efficiency permits many unequal distributions as long as no Pareto improvement is possible."
      },
      {
        "misconception": "The first welfare theorem says that nobody loses from a competitive equilibrium.",
        "correction": "It says the equilibrium is Pareto efficient. It does not compare that allocation with every alternative distribution."
      },
      {
        "misconception": "The second welfare theorem recommends any Pareto-efficient allocation.",
        "correction": "It shows that an efficient allocation may be decentralized using appropriate transfers. Choosing the distribution remains a normative decision."
      },
      {
        "misconception": "Existence guarantees uniqueness and stability.",
        "correction": "Existence, uniqueness, and stability are logically separate equilibrium properties."
      },
      {
        "misconception": "A Pigouvian tax necessarily makes every household better off.",
        "correction": "It can improve allocative efficiency, but winners and losers depend on tax incidence, revenue use, ownership patterns, and adjustment costs."
      }
    ],
