    "key_concepts": [
      {
        "term": "Constructivism",
        "working_definition": "A view of learning in which learners actively build and revise mental models through interaction with prior knowledge, experience, other people, and the learning environment."
      },
      {
        "term": "Schema",
        "working_definition": "An organized mental framework that helps a person understand and interpret new information."
      },
      {
        "term": "Assimilation",
        "working_definition": "The process of incorporating new information into an existing schema without substantially changing the schema."
      },
      {
        "term": "Accommodation",
        "working_definition": "The process of changing existing schemas when new experiences or information do not fit the current understanding."
      },
      {
        "term": "Disequilibrium",
        "working_definition": "A gap or inconsistency between what a learner currently understands and what the learner encounters."
      },
      {
        "term": "Zone of Proximal Development",
        "working_definition": "The range between what a learner can do independently and what the learner can accomplish with guidance or support from a more knowledgeable other."
      },
      {
        "term": "Scaffolding",
        "working_definition": "Temporary support, such as modeling, prompts, examples, or feedback, that helps a learner perform a task and is gradually removed as independence increases."
      },
      {
        "term": "Guided Discovery",
        "working_definition": "An inquiry process in which learners actively explore and discover relationships while receiving strategic guidance from the teacher."
      },
      {
        "term": "Advance Organizer",
        "working_definition": "A bridge that connects new knowledge with relevant prior concepts and an organizing framework."
      },
      {
        "term": "Metacognitive Reflection",
        "working_definition": "The process of thinking about one's own learning strategies, understanding, mistakes, and future actions."
      }
