  "structured_jurisprudential_analysis_method": [
    {
      "step": 1,
      "action": "Frame the legal question",
      "questions": [
        "Is the question one of interpretation, jurisdiction, admissibility, violation, state responsibility, or remedy?",
        "What decision is requested, and by which institution?"
      ]
    },
    {
      "step": 2,
      "action": "Identify the applicable law",
      "questions": [
        "Which treaty provisions apply?",
        "Is custom, general principles of law, soft law, or a peremptory norm relevant?",
        "What is the legal status and institutional authority of each source?"
      ]
    },
    {
      "step": 3,
      "action": "Establish jurisdiction and admissibility",
      "questions": [
        "Is the state party to the relevant instrument?",
        "Does the body have competence over the dispute?",
        "Has the claim been brought by a state, an individual, a commission, or another authorized body?",
        "Are applicable time limits, reservations, declarations, and procedural requirements satisfied?"
      ]
    },
    {
      "step": 4,
      "action": "Interpret the legal standard",
      "questions": [
        "What do the relevant terms mean in their textual, contextual, and systematic setting?",
        "What object and purpose should guide the interpretation?",
        "Has subsequent practice or relevant jurisprudence developed the standard?"
      ]
    },
    {
      "step": 5,
      "action": "Apply the standard to material facts",
      "questions": [
        "What facts are required to establish the legal standard?",
        "Does the evidence satisfy each element?",
        "Are causation, attribution, intent, knowledge, or reasonable foreseeability relevant?"
      ]
    },
    {
      "step": 6,
      "action": "Test limitations and counterarguments",
      "questions": [
        "Has the state shown a valid limitation, justification, or derogation?",
        "Could the objective have been achieved by a less restrictive measure?",
        "Would the State's position create discrimination or disproportionate harm?"
      ]
    },
    {
      "step": 7,
      "action": "Form the legal conclusion",
      "questions": [
        "What is the most persuasive result?",
        "What uncertainties or counter-reading remain?",
        "Is the conclusion based on precedent, reasoning, analogy, or persuasive comparative jurisprudence?"
      ]
    },
    {
      "step": 8,
      "action": "Determine consequences",
      "questions": [
        "Should the finding include cessation, non-repetition, restitution, compensation, rehabilitation, or satisfaction?",
        "Can the selected body issue the proposed remedy?",
        "What implementation issues may arise?"
      ]
    }
  ],
