  "common_misconceptions_to_correct": [
    {
      "misconception": "The Universal Declaration of Human Rights is a binding treaty.",
      "correction": "It is not itself a treaty, but it can provide evidence of customary law and interpretive guidance."
    },
    {
      "misconception": "Soft law can never be legally relevant.",
      "correction": "Soft law is generally not a binding source in the same way as a treaty, but it may influence interpretation, subsequent practice, institutional reasoning, and state conduct."
    },
    {
      "misconception": "A finding that a restriction was necessary automatically establishes a human rights violation.",
      "correction": "Students must first identify the protected right, the state's burden, and whether the restriction was disproportionate or otherwise defective."
    },
    {
      "misconception": "The margin of appreciation allows states to choose any human rights policy.",
      "correction": "It is limited by the text, legitimate aims, necessity, proportionality, and relevant case law within the regional system."
    },
    {
      "misconception": "All recommendations issued by UN human rights bodies are equivalent to court judgments.",
      "correction": "Their authority and legal effects differ by body, mandate, procedure, and the applicable source instrument."
    },
    {
      "misconception": "Human rights obligations apply only inside national territory.",
      "correction": "Application may depend on the instrument, state control or authority, extraterritorial jurisdiction clauses, and applicable customary duties such as non-refoulement."
    },
    {
      "misconception": "A human rights violation automatically proves the responsible individual committed a crime.",
      "correction": "State responsibility, individual criminal responsibility, and international responsibility of non-state actors involve distinct legal tests."
    }
