  "glossary": [
    {
      "term": "Jus cogens",
      "definition": "Peremptory norms of international law from which no derogation is permitted."
    },
    {
      "term": "Erga omnes",
      "definition": "Obligations of universal concern or obligations owed to the international community as a whole, distinct from ordinary bilateral treaty relations."
    },
    {
      "term": "Customary international law",
      "definition": "General practice accepted as law, commonly assessed through state practice and opinio juris."
    },
    {
      "term": "Non-refoulement",
      "definition": "A principle generally prohibiting the transfer of a person to a state where there is a real risk of persecution, torture, or certain other irreparable harm."
    },
    {
      "term": "Proportionality",
      "definition": "An analytical structure assessing legality, legitimate aim, suitability, necessity, and the balance between the measure and the harm produced."
    },
    {
      "term": "Margin of appreciation",
      "definition": "A doctrine, especially associated with the European Convention system, allowing some state discretion within internationally defined limits."
    },
    {
      "term": "Derogation",
      "definition": "A temporary departure from a treaty obligation during a formally defined emergency, subject to strict requirements."
    },
    {
      "term": "Due diligence",
      "definition": "The obligation to take reasonable and effective measures to protect rights, prevent harm, investigate violations, and provide appropriate remedies."
    },
    {
      "term": "State responsibility",
      "definition": "The legal attribution and consequences of conduct or omissions attributable to a state that breach an applicable international obligation."
    },
    {
      "term": "Reparation",
      "definition": "Measures intended to remedy the consequences of an internationally wrongful act, including restitution, compensation, rehabilitation, satisfaction, and guarantees of non-repetition."
    }
  ],
