    "glossary": [
      {
        "term": "Stare decisis",
        "definition": "The principle that courts generally adhere to relevant prior decisions when the same legal issue and materially similar legal conditions are present."
      },
      {
        "term": "Precedent",
        "definition": "A prior judicial decision used as legal authority for deciding a later case."
      },
      {
        "term": "Binding precedent",
        "definition": "Authority that a court must follow because of the source, hierarchy, jurisdiction, and subject matter of the decision."
      },
      {
        "term": "Persuasive precedent",
        "definition": "A decision that may help a court reason but does not formally control its outcome."
      },
      {
        "term": "Vertical precedent",
        "definition": "The authority of a higher court over a lower court within the same hierarchy."
      },
      {
        "term": "Horizontal precedent",
        "definition": "The authority of a prior decision of the same court or the same level of court, subject to jurisdiction-specific rules."
      },
      {
        "term": "Ratio decidendi",
        "definition": "The legal principle or principles necessary to the decision."
      },
      {
        "term": "Obiter dictum",
        "definition": "A statement in a judgment that is not necessary to the result and is therefore generally not binding."
      },
      {
        "term": "Material facts",
        "definition": "Facts that are legally relevant because changing them could change the application of the legal rule or the result."
      },
      {
        "term": "Distinguish",
        "definition": "To decide that a precedent does not apply because there is a material factual or legal difference."
      },
      {
        "term": "Overrule",
        "definition": "To invalidate or replace an earlier precedent through a decision by a court with authority to do so."
      },
      {
        "term": "Controlling authority",
        "definition": "The highest relevant primary or judicial authority that must govern the issue in the particular jurisdiction."
      },
      {
        "term": "Law of the case",
        "definition": "A doctrine concerning what may be reconsidered within the same litigation; it is distinct from stare decisis across separate cases."
      }
    ],
