    "common_misconceptions_and_corrections": [
      {
        "misconception": "Agency theory argues that managers should not receive decision-making authority.",
        "correction": "Agency theory recognizes that delegation and specialization can create value. It asks how authority should be monitored and aligned."
      },
      {
        "misconception": "All shareholders form one principal with a single preference.",
        "correction": "Shareholders may have different horizons, risk preferences, voting strategies, and private interests. A controlling owner may become the de facto principal."
      },
      {
        "misconception": "Agency cost means only auditing and supervision expenses.",
        "correction": "Agency cost also includes bonding costs and residual loss."
      },
      {
        "misconception": "An independent board automatically removes agency problems.",
        "correction": "Independence is one condition. Effectiveness also depends on information, expertise, incentives, time, culture, and willingness to challenge management."
      },
      {
        "misconception": "More monitoring is always better.",
        "correction": "Excessive monitoring consumes resources and may reduce managerial autonomy, entrepreneurship, or information sharing."
      },
      {
        "misconception": "A related-party transaction proves misconduct.",
        "correction": "It may create elevated conflict risk and requires independent review, transparency, and fair-value evidence. A conclusion of misconduct requires stronger evidence."
      },
      {
        "misconception": "A governance mechanism has no downside.",
        "correction": "Mechanisms can shift costs, create new conflicts, or encourage strategic behavior. Evaluation must consider countervailing agency costs."
      }
