  "core_concepts": [
    {
      "term": "Bureaucracy",
      "working_definition": "An organization characterized in varying degrees by hierarchy, specialization, formal authority, written rules, continuity, and impersonal administration."
    },
    {
      "term": "Ideal type",
      "working_definition": "A deliberately simplified analytical model used to compare real organizations; it is not a perfect organizational blueprint."
    },
    {
      "term": "Formal rationality",
      "working_definition": "Decision-making based on general rules, consistency, calculability, and procedures rather than personal preferences."
    },
    {
      "term": "Hierarchy",
      "working_definition": "A clear structure of authority, responsibility, communication, and supervision."
    },
    {
      "term": "Impersonality",
      "working_definition": "Applying the same official rules to cases without favoritism; it does not mean indifference to human dignity or due process."
    },
    {
      "term": "Goal displacement",
      "working_definition": "A situation in which adherence to bureaucratic rules becomes an end in itself rather than a means toward public objectives."
    },
    {
      "term": "Bureaucratic overshoot or budget maximization",
      "working_definition": "The tendency of officials or agencies to expand resources, tasks, or organizational control beyond what is needed for efficient performance."
    },
    {
      "term": "Principal-agent problem",
      "working_definition": "The difficulty of ensuring that officials acting as agents pursue the objectives of elected principals, citizens, and the public interest when goals are complex and information is asymmetric."
    },
    {
      "term": "Street-level bureaucracy",
      "working_definition": "The work of frontline officials who frequently exercise discretion when policy rules, resources, time, and client needs are incomplete or conflicting."
    },
    {
      "term": "New Public Management",
      "working_definition": "A reform paradigm emphasizing performance measurement, service standards, managerial autonomy, user orientation, competition, and results-based accountability."
    },
    {
      "term": "New Public Service",
      "working_definition": "A democratic reform paradigm emphasizing public interest, citizen participation, co-production, responsiveness, and stewardship."
    }
  ],
