  "classroom_activity_design": {
    "organizational_strategy": "Use a running case, small-group roles, and progressively complex evaluation tasks. Each session ends with a brief individual exit ticket.",
    "sessions": [
      {
        "session": 1,
        "title": "Evaluation Foundations, Theory, and Logic Models",
        "duration_minutes": 90,
        "learning_focus": [
          "evaluation purpose and criteria",
          "evaluation theories",
          "evaluation questions",
          "logic models"
        ],
        "activities": [
          {
            "time_minutes": "0-10",
            "activity": "Diagnostic opening",
            "teacher_action": "Present the clean-air case and ask whether the policy succeeded.",
            "student_action": "Vote based on evidence, intuition, or stakeholder preference.",
            "output": "Initial list of success indicators and assumptions",
            "purpose": "Reveal differences in how people define policy success"
          },
          {
            "time_minutes": "10-25",
            "activity": "Interactive lecture",
            "teacher_action": "Explain evaluation definitions, criteria, theory, design, and method distinctions.",
            "student_action": "Complete a concept map with one example for each term.",
            "output": "Individual concept map",
            "purpose": "Establish common conceptual language"
          },
          {
            "time_minutes": "25-40",
            "activity": "Stakeholder role activity",
            "teacher_action": "Assign students to public-health, environmental, business, resident, and budget perspectives.",
            "student_action": "Identify the policy problem, desired outcomes, risks, and preferred success criteria from the assigned perspective.",
            "output": "Stakeholder criterion matrix",
            "purpose": "Demonstrate multidimensional and political definitions of success"
          },
          {
            "time_minutes": "40-60",
            "activity": "Logic-model construction",
            "teacher_action": "Facilitate group work and ask groups to include assumptions and external factors.",
            "student_action": "Build a logic model for the clean-air policy.",
            "output": "Inputs-activities-outputs-outcomes-impact diagram",
            "purpose": "Connect theory to observable indicators"
          },
          {
            "time_minutes": "60-70",
            "activity": "Gallery walk",
            "teacher_action": "Ask probing questions about missing causal links.",
            "student_action": "Compare models and leave one question or suggestion on another group's poster.",
            "output": "Peer feedback",
            "purpose": "Improve causal reasoning through peer review"
          },
          {
            "time_minutes": "70-83",
            "activity": "Indicator design challenge",
            "teacher_action": "Give students a list of proposed indicators.",
            "student_action": "Classify each indicator as input, process, output, outcome, or impact and assess its validity and equity implications.",
            "output": "Corrected indicator table",
            "purpose": "Practice outcome measurement"
          },
          {
            "time_minutes": "83-90",
            "activity": "Exit ticket",
            "teacher_action": "Ask students to formulate one effectiveness question and one equity question.",
            "student_action": "Submit both questions individually.",
            "output": "Short written response",
            "purpose": "Assess individual understanding"
          }
        ]
      },
      {
        "session": 2,
        "title": "Causal Inference and Quantitative Evaluation",
        "duration_minutes": 90,
        "learning_focus": [
          "counterfactuals",
          "internal validity",
          "quasi-experimental designs",
          "interpretation of estimates"
        ],
        "activities": [
          {
            "time_minutes": "0-10",
            "activity": "Retrieval warm-up",
            "teacher_action": "Display a policy claim and ask students to list every alternative explanation.",
            "student_action": "Identify confounders and missing counterfactual information.",
            "output": "Alternative-explanation list",
            "purpose": "Reinforce causal reasoning"
          },
          {
            "time_minutes": "10-30",
            "activity": "Design selection workshop",
            "teacher_action": "Present randomized, difference-in-differences, regression discontinuity, interrupted time series, matching, and synthetic-control designs.",
            "student_action": "Complete a matrix recording assumptions, data requirements, strengths, and limitations.",
            "output": "Causal-design comparison matrix",
            "purpose": "Learn to match designs to identification problems"
          },
          {
            "time_minutes": "30-48",
            "activity": "Method-matching card sort",
            "teacher_action": "Provide evaluation scenarios such as program take-up, a threshold rule, and a citywide intervention.",
            "student_action": "Match each scenario with a feasible design and justify the choice.",
            "output": "Design cards with written justification",
            "purpose": "Apply design-selection rules"
          },
          {
            "time_minutes": "48-63",
            "activity": "Difference-in-differences exercise",
            "teacher_action": "Walk students through the calculation using the case data.",
            "student_action": "Calculate the estimate and distinguish the mathematical result from the causal claim.",
            "output": "Calculation and interpretation",
            "purpose": "Practice quantitative interpretation"
          },
          {
            "time_minutes": "63-80",
            "activity": "Validity-threat analysis",
            "teacher_action": "Give groups a scenario involving weather, migration, selective program entry, or policy spillover.",
            "student_action": "Identify the threat, assess its direction, and propose a mitigation.",
            "output": "Validity threat-control table",
            "purpose": "Develop practical research judgment"
          },
          {
            "time_minutes": "80-90",
            "activity": "Exit ticket",
            "teacher_action": "Ask why a statistically significant before-and-after change may still be misleading.",
            "student_action": "Write a two- or three-sentence explanation.",
            "output": "Individual response",
            "purpose": "Check understanding of causal inference"
          }
        ]
      },
      {
        "session": 3,
        "title": "Mixed Methods, Economic and Equity Evaluation, and Policy Communication",
        "duration_minutes": 90,
        "learning_focus": [
          "qualitative and mixed-method evidence",
          "economic evaluation",
          "equity and ethics",
          "policy communication"
        ],
        "activities": [
          {
            "time_minutes": "0-12",
            "activity": "Evidence-method matching",
            "teacher_action": "Present questions about implementation, mechanisms, outcomes, and policy meaning.",
            "student_action": "Match questions with interviews, surveys, administrative analysis, observation, or process tracing.",
            "output": "Method justification table",
            "purpose": "Connect questions to evidence types"
          },
          {
            "time_minutes": "12-30",
            "activity": "Mini-lecture on mixed and economic methods",
            "teacher_action": "Explain integration designs, cost analysis, cost-effectiveness, cost-benefit, and multi-criteria analysis.",
            "student_action": "Annotate the policy case with possible quantitative and qualitative evidence.",
            "output": "Evidence inventory",
            "purpose": "Broaden evaluation options"
          },
          {
            "time_minutes": "30-50",
            "activity": "Mixed-method design studio",
            "teacher_action": "Require each group to select and justify a mixed-method integration model.",
            "student_action": "Integrate sensors, administrative records, surveys, and interviews into one coherent design.",
            "output": "Mixed-method evaluation matrix",
            "purpose": "Practice integration rather than listing methods"
          },
          {
            "time_minutes": "50-65",
            "activity": "Equity and ethics audit",
            "teacher_action": "Provide examples of unequal sensor placement, re-identification risk, and low participation by marginalized groups.",
            "student_action": "Identify an ethical or equity problem and redesign a data-collection or reporting component.",
            "output": "Risk and mitigation table",
            "purpose": "Make ethical and distributional concerns operational"
          },
          {
            "time_minutes": "65-80",
            "activity": "Policy briefing",
            "teacher_action": "Assign an expand, redesign, or terminate decision and a two-minute briefing limit.",
            "student_action": "Present the recommendation, evidence, uncertainty, equity implications, and monitoring plan.",
            "output": "Two-minute oral briefing",
            "purpose": "Practice evidence-based decision communication"
          },
          {
            "time_minutes": "80-90",
            "activity": "Peer review and exit ticket",
            "teacher_action": "Use a checklist covering logic, method fit, assumptions, equity, ethics, and clarity.",
            "student_action": "Review a peer product and identify one strength and one revision.",
            "output": "Peer-review comment and final reflection",
            "purpose": "Assess achievement of learning objectives"
          }
        ]
      }
    ]
  },
