  "anticipated_misconceptions_and_corrections": [
    {
      "misconception": "If outcomes improved after implementation, the policy caused the improvement.",
      "correction": "Ask for a plausible counterfactual and identify alternative explanations."
    },
    {
      "misconception": "Randomized experiments are always the best method.",
      "correction": "Emphasize ethical, political, practical, and external-validity constraints."
    },
    {
      "misconception": "Qualitative evidence is opinion rather than evidence.",
      "correction": "Show systematic sampling, interview protocols, coding procedures, reflexivity, and triangulation."
    },
    {
      "misconception": "Cost-benefit analysis is completely objective because it uses numerical values.",
      "correction": "Identify assumptions, discounting choices, monetization disputes, and distributional effects."
    },
    {
      "misconception": "A non-significant result proves that the policy had no effect.",
      "correction": "Discuss confidence intervals, statistical power, measurement error, and practical significance."
    },
    {
      "misconception": "Average impacts describe every community.",
      "correction": "Require disaggregated results and separate allocation effects from outcome effects."
    },
    {
      "misconception": "Stakeholder participation guarantees an equitable evaluation.",
      "correction": "Discuss unequal resources, representation barriers, power relations, and compensatory support."
    }
  ],
