      {
        "term": "Ventricle",
        "definition": "A lower heart chamber that pumps blood out of the heart."
      },
      {
        "term": "Valve",
        "definition": "A structure that helps prevent the backward flow of blood."
      },
      {
        "term": "Artery",
        "definition": "A blood vessel that carries blood away from the heart."
      },
      {
        "term": "Vein",
        "definition": "A blood vessel that carries blood toward the heart."
      },
