  "classroom_activity_design": [
    {
      "phase": "1. Engagement and diagnostic assessment",
      "time_minutes": 5,
      "teacher_actions": [
        "Show an unlabeled heart image.",
        "Ask learners to indicate where oxygenated and deoxygenated blood enter and leave the heart.",
        "Use a short stethoscope demonstration or heartbeat recording if available."
      ],
      "student_actions": [
        "Observe the image and make an initial prediction.",
        "Identify any familiar structures.",
        "Record one question about the internal anatomy."
      ],
      "assessment": "Use responses to identify prior knowledge and likely misconceptions."
    },
    {
      "phase": "2. Orientation, coverings, and heart wall",
      "time_minutes": 7,
      "teacher_actions": [
        "Use the heart model to demonstrate the base, apex, anterior surface, and diaphragmatic surface.",
        "Point out the interatrial and interventricular septa.",
        "Compare the fibrous pericardium, serous pericardium, epicardium, myocardium, and endocardium."
      ],
      "student_actions": [
        "Orient the model from the learner's anatomical perspective.",
        "Label the three heart-wall layers on a worksheet.",
        "Explain the difference between the heart wall and its pericardial covering."
      ],
      "assessment": "Ask learners to point to the apex, base, interventricular septum, and myocardium."
    },
    {
      "phase": "3. Guided model exploration",
      "time_minutes": 13,
      "teacher_actions": [
        "Open the model and identify the right and left atria and ventricles.",
        "Trace vessel openings to their chambers.",
        "Identify the tricuspid, mitral, pulmonary, and aortic valves.",
        "Show chordae tendineae, papillary muscles, and the fibrous skeleton."
      ],
      "student_actions": [
        "Label structures on an unlabeled diagram.",
        "Check each label with a partner using the model.",
        "Compare the thickness of the right and left ventricular walls."
      ],
      "assessment": "Conduct a quick label check using colored cards or mini-whiteboards."
    },
    {
      "phase": "4. Blood-flow card sort",
      "time_minutes": 7,
      "teacher_actions": [
        "Distribute structure and vessel cards to groups of three or four.",
        "Ask groups to arrange the structures in a loop from the body through both circuits and back.",
        "Require each group to justify the valve that appears between two chambers or vessels."
      ],
      "student_actions": [
        "Arrange the cards using arrows or yarn.",
        "Trace systemic and pulmonary circulation separately.",
        "Explain the route to another group."
      ],
      "assessment": "Evaluate chamber order, valve placement, and vessel direction."
    },
    {
      "phase": "5. Build and test a valve model",
      "time_minutes": 8,
      "teacher_actions": [
        "Provide a paper ring, flexible card or latex material, string, and tape.",
        "Demonstrate a simplified atrioventricular valve with two leaflets and chord-like strings.",
        "Ask learners to compare this with a semilunar valve made from three pocket-shaped flaps."
      ],
      "student_actions": [
        "Construct the valve apparatus.",
        "Pull the strings to represent papillary muscle tension.",
        "Explain how the structures prevent backflow and leaflet prolapse."
      ],
      "assessment": "Learners must state that valve opening is mainly pressure-driven and that chordae stabilize the leaflets."
    },
    {
      "phase": "6. Conduction system and clinical application",
      "time_minutes": 7,
      "teacher_actions": [
        "Place labeled beads or cards along the conduction pathway.",
        "Sequence the sinoatrial node, atrioventricular node, bundle of His, bundle branches, and Purkinje fibers.",
        "Present a short case involving a damaged valve, a septal defect, or blocked coronary artery."
      ],
      "student_actions": [
        "Arrange the conduction structures in order.",
        "Predict how the named condition would affect blood movement, chamber pressure, or heart rhythm."
      ],
      "assessment": "Ask each learner to provide one structure-function relationship and one clinical consequence."
    },
    {
      "phase": "7. Exit assessment",
      "time_minutes": 3,
      "teacher_actions": [
        "Distribute the exit check.",
        "Collect responses and use them to plan the next lesson."
      ],
      "student_actions": [
        "Complete the diagram and short-answer questions independently."
      ],
      "assessment": "Score against the exit-check criteria."
    }
  ],
