      {
        "term": "Antibiotic resistance",
        "definition": "A heritable or stable phenotypic ability to survive and grow at antibiotic concentrations that inhibit or kill susceptible bacteria, commonly reflected by an increased MIC."
      },
      {
        "term": "Intrinsic resistance",
        "definition": "A baseline resistance characteristic naturally associated with a species or lineage, often related to cell envelope, permeability, efflux, or absence of a target."
      },
      {
        "term": "Acquired resistance",
        "definition": "Resistance that develops through mutation or acquisition of foreign DNA."
      },
      {
        "term": "MIC",
        "definition": "Minimum inhibitory concentration; the lowest antibiotic concentration that visibly inhibits visible bacterial growth under defined testing conditions."
      },
      {
        "term": "Horizontal gene transfer",
        "definition": "Transfer of genetic material between bacteria through conjugation, transformation, or transduction."
      },
      {
        "term": "Target modification",
        "definition": "Alteration of the antibiotic target that reduces drug binding, such as changes in PBPs, DNA gyrase, or ribosomal RNA."
      },
      {
        "term": "Target protection",
        "definition": "A mechanism in which a protein protects the target from the antibiotic without substantially altering the target itself."
      },
      {
        "term": "Efflux pump",
        "definition": "An energy-dependent or membrane-associated transport system that lowers the intracellular concentration of an antibiotic."
      },
      {
        "term": "Biofilm",
        "definition": "A community of microorganisms attached to a surface and enclosed in a self-produced matrix that can promote reduced susceptibility and persistence."
      },
      {
        "term": "Fitness cost",
        "definition": "A reduction in growth, survival, or competitive ability associated with carrying or expressing a resistance mechanism."
      }
    ],
