    "core_concepts": [
      {
        "term": "Postmodernism",
        "working_definition": "A contested family of philosophical, literary, and artistic approaches that questions universalizing claims, stable representation, and single centers of authority",
        "look_for": [
          "Skepticism toward totalizing narratives",
          "Self-conscious form",
          "Blurred genres and cultural hierarchies",
          "Concern with authorship, originality, reality, and institutions"
        ]
      },
      {
        "term": "Modernism",
        "working_definition": "A broad family of late nineteenth- and early twentieth-century movements that often explored formal innovation, subjective experience, fragmentation, and new technologies",
        "look_for": [
          "Formal experimentation",
          "Multiple perspectives",
          "Urban, industrial, or psychological themes",
          "Comparison should be based on function and context rather than dates alone"
        ]
      },
      {
        "term": "Poststructuralism",
        "working_definition": "An intellectual approach that examines how language, discourse, difference, and systems of power shape meaning and authority",
        "look_for": [
          "Analysis of unstable meaning",
          "Language as a system",
          "Questioning fixed categories",
          "Overlap with postmodernism but not complete identity"
        ]
      },
      {
        "term": "Grand narrative or metanarrative",
        "working_definition": "A large, overarching account that organizes historical, social, or cultural meaning, such as a universal story of progress or emancipation",
        "look_for": [
          "Attempts to explain a whole society or history",
          "Claims of universal applicability",
          "Postmodern questions to their authority, scope, or hidden assumptions"
        ]
      },
      {
        "term": "Metafiction",
        "working_definition": "Fiction that draws attention to its own construction as a story and to the reader's role in making meaning",
        "look_for": [
          "A narrator comments on storytelling",
          "Fictional and historical accounts are placed in tension",
          "The work exposes gaps, framing devices, or genre conventions"
        ]
      },
      {
        "term": "Fragmentation and polyphony",
        "working_definition": "The use of discontinuous form, multiple voices, competing perspectives, or unresolved narratives",
        "look_for": [
          "Nonlinear structure",
          "Shifts in time, voice, or point of view",
          "Collisions of contradictory accounts",
          "Effects on pacing, reader orientation, and authority"
        ]
      },
      {
        "term": "Intertextuality",
        "working_definition": "The relationship among texts through quotation, allusion, imitation, translation, adaptation, or reference",
        "look_for": [
          "Echoes of earlier works",
          "Rewritten myths, histories, or genres",
          "Readers expected to recognize cultural connections"
        ]
      },
      {
        "term": "Parody and pastiche",
        "working_definition": "Parody imitates a source in order to expose or criticize it; pastiche imitates or combines styles without necessarily criticizing the source",
        "look_for": [
          "The difference between critique and neutral recombination",
          "The choice of source material",
          "The target of imitation",
          "The political or commercial effect of the reference"
        ]
      },
      {
        "term": "Appropriation and remix",
        "working_definition": "The deliberate taking, copying, sampling, or transforming of existing cultural material",
        "look_for": [
          "Recontextualization",
          "Questions about originality and credit",
          "Potential critique of commodity culture or authority",
          "Ethical questions involving consent, power, compensation, and audience"
        ]
      },
      {
        "term": "Simulacrum and hyperreality",
        "working_definition": "A copy, representation, or constructed image that becomes difficult to distinguish from, or more influential than, the thing it supposedly represents",
        "look_for": [
          "Images without stable originals",
          "Repeated signs and representations",
          "The construction of reality through media or spectacle"
        ]
      },
      {
        "term": "Institutional critique",
        "working_definition": "An artistic practice that makes the museum, gallery, market, authorial institution, or broader cultural authority part of the work's subject",
        "look_for": [
          "Display context",
          "Labels and catalog conventions",
          "The boundary between artwork and ordinary object",
          "The role of ownership, exhibition, and cultural value"
        ]
      },
      {
        "term": "Audience participation",
        "working_definition": "A work that actively involves viewers, readers, users, or contributors in producing or interpreting its meaning",
        "look_for": [
          "Interactive or online formats",
          "Viewer-generated content",
          "Changing works across audiences or contexts",
          "Questions about authorship, community, data, and control"
        ]
      }
    ],
