  "key_points": [
    {
      "point": "Bias is not always consciously intended",
      "explanation": "People can form rapid judgments before they have time to reflect. Lack of conscious intent does not prevent behavior from producing unequal or unfair effects."
    },
    {
      "point": "Implicit bias usually operates through automatic mental processes",
      "explanation": "It may influence what people notice, how they interpret ambiguous information, what they remember, whom they help, and which questions they ask."
    },
    {
      "point": "Small judgments can create cumulative effects",
      "explanation": "Repeated differences in attention, opportunities, feedback, trust, or discipline can become patterns at the group or organizational level."
