{
  "title": "The Neural Basis of Decision Making",
  "knowledge_point": "How distributed brain networks represent information, evaluate options, select actions, and learn from outcomes",
  "lesson_overview": {
    "suggested_audience": "Introductory university students in psychology, neuroscience, or cognitive science; adaptable for advanced secondary students",
    "duration_minutes": 90,
    "class_size": "16–40 students",
    "prerequisites": [
      "Basic knowledge of neurons, synapses, and brain regions",
      "Familiarity with concepts such as reward, probability, and learning"
    ],
    "central_question": "How does the brain turn information and goals into an action, and how does it learn from the result?",
    "big_idea": "Decision making is a distributed, dynamic, and recurrent process involving multiple neural systems rather than a single decision-making center.",
    "lesson_narrative": "Students begin with a simple everyday choice, examine the stages of decision making, map the relevant brain networks, interpret evidence from a hypothetical neuroscience case, and apply a simplified dopamine prediction-error model."
  },
  "teaching_objectives": [
    {
      "id": "O1",
      "objective": "Define decision making and distinguish its major stages, including goal maintenance, evidence integration, valuation, action selection, monitoring, and learning.",
      "alignment": "Knowledge and understanding"
    },
    {
      "id": "O2",
      "objective": "Explain the main contributions of the prefrontal cortex, vmPFC, OFC, ACC, insula, basal ganglia, striatum, and midbrain dopamine systems in a canonical decision-making network.",
      "alignment": "Knowledge and application"
    },
    {
      "id": "O3",
      "objective": "Use the simplified equation δ = r − V to calculate and interpret reward prediction error.",
      "alignment": "Procedural and conceptual application"
    },
    {
      "id": "O4",
      "objective": "Distinguish correlational evidence from stronger causal evidence in neuroscience research.",
      "alignment": "Scientific reasoning"
    },
    {
      "id": "O5",
      "objective": "Analyze a hypothetical study and identify both a supported interpretation and an alternative explanation for the findings.",
      "alignment": "Analysis and evaluation"
    },
    {
      "id": "O6",
      "objective": "Collaborate to construct an integrated neural and computational model of decision making.",
      "alignment": "Communication and collaboration"
    }
  ],
  "key_points": [
    {
      "point": "Decision making is distributed across interacting networks.",
      "explanation": "Sensory, executive, valuation, action-selection, monitoring, and learning systems make different contributions to the same decision."
    },
    {
      "point": "The lateral prefrontal cortex supports goals, working memory, rules, and maintenance of task-relevant information.",
      "explanation": "It helps keep a current goal or decision rule active while evidence and alternatives are considered."
    },
    {
      "point": "The ventromedial prefrontal cortex and orbitofrontal cortex often represent option value, expected outcome, and context-dependent preferences.",
      "explanation": "A region does not represent a fixed value in all situations; valuation depends on goals, history, emotion, and current state."
    },
    {
      "point": "The anterior cingulate cortex and insula contribute to monitoring, conflict, expected outcomes, significance, and interoceptive information.",
      "explanation": "These regions should not be labeled only as conflict or risk centers because their activity is context dependent."
    },
    {
      "point": "The basal ganglia help select, initiate, suppress, and learn actions.",
      "explanation": "The dorsal and ventral striatum contribute differently to goal-directed behavior, habits, reward learning, action vigor, and action selection."
    },
    {
      "point": "Midbrain dopamine is involved in learning, motivation, movement vigor, and the updating of predictions.",
      "explanation": "In a simplified reinforcement-learning model, a phasic dopamine signal reflects reward prediction error, but real dopamine signals are more diverse."
    },
    {
      "point": "Decision making is recurrent rather than strictly linear.",
      "explanation": "Evidence, valuation, selection, monitoring, and learning continually influence one another."
    }
  ],
  "key_difficulties": [
    {
      "difficulty": "Assigning one fixed function to each brain region",
      "reason": "Most functions involve distributed, overlapping, and context-dependent networks.",
      "teaching_strategy": "Use a network diagram with bidirectional arrows and repeatedly ask what computation, rather than merely what region, is being performed."
    },
    {
      "difficulty": "Moving between levels of explanation",
      "reason": "Students may connect a region directly to a behavior without explaining the intervening computation.",
      "teaching_strategy": "Require the sequence region or system, neural computation, behavioral effect, and supporting evidence."
    },
    {
      "difficulty": "Treating fMRI activation as proof of causation",
      "reason": "BOLD activation can reflect several processes and may be correlated with, rather than cause, a behavior.",
      "teaching_strategy": "Compare imaging, lesion, electrophysiological, pharmacological, and animal optogenetic evidence."
    },
    {
      "difficulty": "Understanding reward prediction error",
      "reason": "Students may confuse expected reward with received reward or interpret a negative prediction error as negative pleasure.",
      "teaching_strategy": "Use numerical examples, sign checks, and the statement that outcomes better than expected tend to increase learning, whereas outcomes worse than expected tend to decrease it."
    },
    {
      "difficulty": "Recognizing that value depends on context",
      "reason": "The same option may have different value under different goals, resource states, or histories.",
      "teaching_strategy": "Compare the value of the same snack before and after eating, or the value of a route under different time pressures."
    }
  ],
  "core_content": {
    "working_definition": "Decision making is the selection of an action or response based on goals, available evidence, expected consequences, and previous experience.",
    "canonical_process": [
      {
        "stage": "1. Establish goals and current state",
        "description": "Internal goals, needs, rules, and environmental conditions influence which information matters."
      },
      {
        "stage": "2. Encode evidence and retrieve context",
        "description": "Sensory systems represent current information, while memory systems contribute prior experiences and contextual knowledge."
      },
      {
        "stage": "3. Accumulate evidence and evaluate options",
        "description": "Evidence is integrated over time, and alternatives are assigned subjective values based on probability, effort, delay, risk, and context."
      },
      {
        "stage": "4. Select and initiate an action",
        "description": "Competing actions are selected through frontostriatal and basal-ganglia circuits."
      },
      {
        "stage": "5. Monitor and revise the choice",
        "description": "Feedback is evaluated for conflict, error, or changed conditions, potentially leading to revision or inhibition."
      },
      {
        "stage": "6. Learn from the outcome",
        "description": "The difference between expected and received outcomes updates future values, predictions, and action tendencies."
      }
    ],
    "network_guide": [
      {
        "system": "Goals and working memory",
        "example_regions": [
          "Dorsolateral prefrontal cortex",
          "Posterior parietal cortex"
        ],
        "main_contribution": "Maintains goals, task rules, choices, and relevant information while suppressing distraction."
      },
      {
        "system": "Valuation and preference",
        "example_regions": [
          "Ventromedial prefrontal cortex",
          "Orbitofrontal cortex",
          "Striatum"
        ],
        "main_contribution": "Represents expected outcomes and helps compare the subjective value of alternatives."
      },
      {
        "system": "Monitoring and internal state",
        "example_regions": [
          "Anterior cingulate cortex",
          "Insula"
        ],
        "main_contribution": "Contributes to conflict monitoring, outcome evaluation, significance, and interoceptive information."
      },
      {
        "system": "Action selection",
        "example_regions": [
          "Dorsal striatum",
          "Ventral striatum",
          "Globus pallidus",
          "Subthalamic nucleus"
        ],
        "main_contribution": "Selects, initiates, suppresses, and learns actions through direct and indirect basal-ganglia pathways."
      },
      {
        "system": "Learning and motivation",
        "example_regions": [
          "Substantia nigra pars compacta",
          "Ventral tegmental area",
          "Prefrontal cortex",
          "Striatum"
        ],
        "main_contribution": "Modulates learning, action vigor, motivation, and updates to expected outcomes."
      },
      {
        "system": "Memory, context, and emotional salience",
        "example_regions": [
          "Hippocampus",
          "Temporal cortex",
          "Amygdala"
        ],
        "main_contribution": "Supplies past experience, contextual information, and learned emotional or motivational significance."
      },
      {
        "system": "Action execution",
        "example_regions": [
          "Motor cortex",
          "Supplementary and premotor areas",
          "Brainstem motor systems"
        ],
        "main_contribution": "Executes or adjusts the selected movement, although the need for overt movement varies by task."
      }
    ],
    "computational_principles": [
      {
        "concept": "Subjective value",
        "definition": "A context-dependent representation of how desirable or costly an outcome is relative to current goals and alternatives.",
        "example": "A difficult task may have high value when an important reward is available but low value under severe time pressure."
      },
      {
        "concept": "Evidence accumulation",
        "definition": "The progressive integration of evidence toward a decision threshold.",
        "example": "A person accumulates evidence for which side of a display contains a target before responding."
      },
      {
        "concept": "Action selection",
        "definition": "Competition among possible actions, influenced by expected value, effort, learned habits, and current context.",
        "example": "A familiar route may be selected automatically even when a new route has a slightly better predicted outcome."
      },
      {
        "concept": "Reward prediction error",
        "definition": "In a simplified model, δ = r − V, where r is the received reward and V is the expected reward before the outcome.",
        "interpretation": "A positive error means the outcome was better than expected; a negative error means it was worse than expected; zero means the outcome was fully predicted."
      },
      {
        "concept": "Goal-directed behavior versus habit",
        "definition": "Goal-directed behavior is sensitive to current outcomes and goals, whereas habits are learned stimulus-response tendencies that can persist despite changed goals.",
        "example": "Choosing a new route after receiving better feedback is more goal-directed; repeating a previously rewarded route is more habitual."
      }
    ],
    "evidence_methods": [
      {
        "method": "Functional imaging",
        "strength": "Shows distributed activity associated with a task or condition.",
        "limitation": "BOLD signals are temporally delayed and correlational; activation does not by itself prove a causal role."
      },
      {
        "method": "Electrophysiology",
        "strength": "Provides millisecond-scale timing and can reveal when populations encode a decision variable.",
        "limitation": "Recording is technically difficult and does not automatically reveal the full computation performed by a region."
      },
      {
        "method": "Lesion studies",
        "strength": "Can provide evidence about necessary brain function in humans.",
        "limitation": "Lesions may cause compensation, disconnection effects, or changes beyond the damaged region."
      },
      {
        "method": "Pharmacological manipulation",
        "strength": "Can test whether neurotransmitters contribute to behavior.",
        "limitation": "Drugs often affect many circuits and may not be specific to one decision process."
      },
      {
        "method": "Optogenetic or chemogenetic manipulation",
        "strength": "Can provide strong causal evidence, especially in animal models.",
        "limitation": "Applicability to human cognition and natural decision making requires caution."
      }
    ],
    "common_misconceptions": [
      {
        "misconception": "There is one specific decision-making center in the brain.",
        "correction": "Decision making depends on interacting sensory, prefrontal, limbic, basal-ganglia, and motor networks."
      },
      {
        "misconception": "Dopamine is simply the brain's pleasure chemical.",
        "correction": "Dopamine contributes to prediction, learning, motivation, movement vigor, and reinforcement, not only pleasure."
      },
      {
        "misconception": "More brain activation means a better decision.",
        "correction": "The location, timing, pattern, and interpretation of activity matter; increased activity may represent difficulty, conflict, or monitoring rather than preference."
      },
      {
        "misconception": "An fMRI activation proves that the activated region causes the behavior.",
        "correction": "Imaging is primarily correlational. Causal conclusions require converging methods or experimental manipulation."
      },
      {
        "misconception": "The prefrontal cortex only makes decisions and the basal ganglia only move muscles.",
        "correction": "Both regions contribute to learning and action selection, and the basal ganglia also participate in cognition, habit, and motivation."
      }
    ]
  },
  "classroom_activity_design": [
    {
      "id": "A1",
      "name": "Everyday Choice Hook",
      "minutes": 5,
      "objective": [
        "O1",
        "O5"
      ],
      "setup": "Display a scenario: A student must choose between tea and coffee, two routes to school, or two possible purchases.",
      "teacher_actions": [
        "Ask students to identify what information is needed before making the choice.",
        "Ask which brain structures might contribute and why.",
        "Collect initial answers without confirming a single correct region list."
      ],
      "student_actions": [
        "Make an individual prediction",
        "Compare predictions with a partner",
        "Share one idea with the class"
      ],
      "output": "Initial claims about the neural basis of decision making",
      "formative_check": "Ask whether decision making begins only when a person consciously deliberates."
    },
    {
      "id": "A2",
      "name": "Diagnostic Concept Sort",
      "minutes": 5,
      "objective": [
        "O1",
        "O2"
      ],
      "setup": "Prepare cards labeled vmPFC, basal ganglia, prediction error, fMRI, working memory, dopamine, action selection, and subjective value.",
      "teacher_actions": [
        "Have students sort the cards into brain system, computational concept, or research method.",
        "Record misconceptions for later review."
      ],
      "student_actions": [
        "Sort the terms individually",
        "Revise the sort after a brief class discussion"
      ],
      "output": "Beginning concept map",
      "formative_check": "Use the results to determine whether vocabulary support is needed."
    },
    {
      "id": "A3",
      "name": "Interactive Mini-Lecture",
      "minutes": 15,
      "objective": [
        "O1",
        "O2"
      ],
      "setup": "Present decision making as a recurrent six-stage process rather than a single event.",
      "teacher_actions": [
        "Teach the stages of goals, evidence, valuation, selection, monitoring, and learning.",
        "Introduce the network guide using a vote-choice example.",
        "Pause twice to ask students to predict the next step."
      ],
      "student_actions": [
        "Complete a partially completed process diagram",
        "Answer polling questions",
        "Identify the roles of systems rather than isolated regions"
      ],
      "output": "Completed six-stage decision-making diagram",
      "formative_check": "Give the scenario change the value of a previously preferred option and ask which stage must be updated."
    },
    {
      "id": "A4",
      "name": "Neural Network Jigsaw",
      "minutes": 15,
      "objective": [
        "O2",
        "O6"
      ],
      "setup": "Assign groups one system: goals and working memory, valuation, monitoring, action selection, learning, or memory and context.",
      "teacher_actions": [
        "Give each group a role card with key structures, a computational contribution, one type of evidence, and one caveat.",
        "Require each group to explain how its system interacts with at least two other systems."
      ],
      "student_actions": [
        "Build a section of a shared network diagram",
        "Place bidirectional arrows between systems",
        "Teach their section to another group"
      ],
      "output": "Class-wide neural network map",
      "formative_check": "Assess whether arrows represent interactions and whether students avoid one-region-one-function claims."
    },
    {
      "id": "A5",
      "name": "Hypothetical Evidence Case",
      "minutes": 15,
      "objective": [
        "O4",
        "O5"
      ],
      "setup": "Provide a fictional study in which vmPFC activity tracks choice value, dorsal striatum activity precedes action initiation, ACC activity increases with conflict, and a lesion is associated with reduced flexible switching.",
      "teacher_actions": [
        "Ask groups to identify the strongest supported interpretation.",
        "Prompt students to generate an alternative explanation for each result.",
        "Ask what additional control or manipulation would strengthen causal inference."
      ],
      "student_actions": [
        "Interpret each finding",
        "Separate observation from interpretation",
        "Classify evidence as correlational or stronger causal evidence",
        "Propose one follow-up experiment"
      ],
      "output": "Evidence table with observation, interpretation, limitation, and follow-up",
      "formative_check": "Require every group to use language such as associated with, consistent with, or supports rather than proves."
    },
    {
      "id": "A6",
      "name": "Reward Prediction Error Calculation",
      "minutes": 10,
      "objective": [
        "O3"
      ],
      "setup": "Introduce the simplified equation δ = r − V.",
      "teacher_actions": [
        "Demonstrate one positive, one negative, and one zero prediction error.",
        "Clarify that a negative prediction error does not mean negative pleasure; it means an outcome was worse than expected."
      ],
      "student_actions": [
        "Calculate prediction error for three trials",
        "Predict whether future choice behavior may change",
        "Explain the answer using learned expectations"
      ],
      "output": "Completed calculation table",
      "formative_check": "Ask students to explain why an expected outcome of 0.4 and a received outcome of 0.4 produce no prediction error."
    },
    {
      "id": "A7",
      "name": "Evidence and Claim Debate",
      "minutes": 10,
      "objective": [
        "O4",
        "O5"
      ],
      "setup": "Use the claim: A brain scan shows that dopamine causes a person to prefer the reward.",
      "teacher_actions": [
        "Assign students to argue for, challenge, or reformulate the claim.",
        "Require references to at least one alternative mechanism and one stronger experiment."
      ],
      "student_actions": [
        "Distinguish correlation from causation",
        "Identify alternative explanations such as value representation, learning, attention, or movement preparation",
        "Propose a stronger causal test"
      ],
      "output": "Revised scientific claim",
      "formative_check": "A strong revision would state that dopamine is associated with reward learning and that its causal contribution must be tested with targeted manipulation."
    },
    {
      "id": "A8",
      "name": "Integrated Concept-Map Synthesis",
      "minutes": 10,
      "objective": [
        "O1",
        "O2",
        "O3",
        "O6"
      ],
      "setup": "Students return to the six-stage process from the mini-lecture.",
      "teacher_actions": [
        "Ask groups to add at least one brain system and one computational idea to every stage.",
        "Encourage correction of misconceptions identified earlier."
      ],
      "student_actions": [
        "Integrate neural and computational information",
        "Add arrows showing feedback from learning to future valuation",
        "Label one limitation of the model"
      ],
      "output": "Final integrated concept map",
      "formative_check": "Use a checklist covering regions, functions, computations, interactions, and evidence."
    },
    {
      "id": "A9",
      "name": "Exit Ticket",
      "minutes": 5,
      "objective": [
        "O1",
        "O2",
        "O3",
        "O4"
      ],
      "setup": "Students answer four short questions independently.",
      "teacher_actions": [
        "Collect the tickets",
        "Use errors to plan the next lesson"
      ],
      "student_actions": [
        "Answer without notes",
        "Submit a brief self-rating of confidence"
      ],
      "output": "Individual evidence of learning",
      "formative_check": "The teacher checks whether students can connect a network to a computation and distinguish evidence from interpretation."
    }
  ],
  "exit_ticket": {
    "questions": [
      "Name two brain systems involved in choosing a snack and state one contribution of each.",
      "If expected reward is 0.6 and received reward is 0.2, calculate δ and explain what it means.",
      "Why does fMRI activation alone not establish that a region causes a decision?",
      "Explain why saying dopamine is simply a pleasure chemical is inaccurate."
    ],
    "scoring": {
      "total_points": 10,
      "criteria": [
        {
          "criterion": "Neural network explanation",
          "points": 4
        },
        {
          "criterion": "Prediction-error calculation and interpretation",
          "points": 2
        },
        {
          "criterion": "Correlation-causation distinction",
          "points": 2
        },
        {
          "criterion": "Scientifically accurate correction of a misconception",
          "points": 2
        }
      ],
      "mastery_threshold": 8
    },
    "expected_answer_key": [
      "Examples of valid systems include sensory or memory systems for representing options, vmPFC or OFC for valuation, and the basal ganglia or striatum for action selection and learning.",
      "δ = 0.2 − 0.6 = −0.4. The outcome was worse than expected and may reduce the learned value of the associated choice.",
      "fMRI BOLD signals are primarily correlational and can reflect several computations. Stronger causal claims require intervention or converging evidence.",
      "Dopamine contributes to prediction error, reinforcement learning, motivation, and movement vigor; it is not identical to pleasure."
    ]
  },
  "assessment_plan": {
    "diagnostic_assessment": {
      "activity": "Diagnostic Concept Sort",
      "purpose": "Identify prior knowledge and vocabulary gaps",
      "grading": "Not graded"
    },
    "formative_assessment": [
      "Whole-class polling during the mini-lecture",
      "Observation of group network map",
      "Questions during the hypothetical case",
      "Reward prediction error practice",
      "Teacher feedback on causal claims"
    ],
    "summative_assessment_for_lesson": {
      "activity": "Exit ticket",
      "weight": "Completion and correctness of the four responses",
      "mastery_indicator": "At least 8 out of 10 points with no major misconception about dopamine or causation"
    },
    "homework": {
      "task": "Create a one-page concept map titled Neural Basis of Decision Making and write a 150-word critique of one claim from a scientific article or news report about dopamine, risk, or reward.",
      "duration_minutes": 30,
      "points": 20,
      "requirements": [
        "Include at least five relevant regions or systems",
        "Connect the structures to named computations",
        "Show at least two interactions between systems",
        "Distinguish correlational from causal evidence",
        "Include one scientific limitation or alternative explanation"
      ]
    },
    "mastery_rubric": [
      {
        "level": "3 - Strong",
        "description": "Accurately integrates regions, computations, interactions, and evidence while acknowledging limitations."
      },
      {
        "level": "2 - Developing",
        "description": "Names the main regions and functions but gives incomplete links to computation or evidence."
      },
      {
        "level": "1 - Beginning",
        "description": "Uses isolated brain-region labels or treats dopamine and fMRI in an oversimplified way."
      }
    ]
  },
  "teaching_materials": {
    "teacher_preparation": [
      "Slides showing the six-stage decision-making cycle",
      "A simplified and clearly labeled brain-network diagram",
      "Role cards for the neural network jigsaw",
      "Hypothetical study handout",
      "Reward prediction error calculation sheet",
      "Exit tickets and rubric",
      "Optional primary-article or news-claim handout"
    ],
    "student_materials": [
      "Decision-making process diagram",
      "Concept cards for the diagnostic sort",
      "Evidence-analysis table",
      "Prediction error practice sheet",
      "Colored pens or digital drawing tools for the concept map"
    ],
    "glossary": [
      {
        "term": "Subjective value",
        "definition": "The desirability or cost of an outcome relative to a person's current goals and alternatives."
      },
      {
        "term": "Evidence accumulation",
        "definition": "The progressive integration of information toward a response threshold."
      },
      {
        "term": "Decision threshold",
        "definition": "The amount of evidence or value needed to trigger a response."
      },
      {
        "term": "Action selection",
        "definition": "The process of favoring one action over competing alternatives."
      },
      {
        "term": "Prediction error",
        "definition": "The difference between an expected outcome and the outcome actually received."
      },
      {
        "term": "Reinforcement learning",
        "definition": "Learning that changes future behavior or expectations based on outcomes."
      },
      {
        "term": "Interoception",
        "definition": "Representation of internal bodily states such as hunger, pain, arousal, or effort."
      },
      {
        "term": "fMRI",
        "definition": "A functional imaging method that measures blood-oxygen changes associated with neural activity."
      }
    ]
  },
  "blackboard_or_slide_layout": [
    {
      "area": "Left",
      "content": "Six stages: goals and state → evidence → valuation → action selection → monitoring → learning"
    },
    {
      "area": "Center",
      "content": "Network map with prefrontal cortex, vmPFC/OFC, ACC/insula, basal ganglia/striatum, dopamine, and memory systems"
    },
    {
      "area": "Right",
      "content": "Computational ideas: subjective value, evidence accumulation, action threshold, reward prediction error"
    },
    {
      "area": "Bottom",
      "content": "Evidence ladder: imaging → recording → lesion or drug → targeted manipulation, accompanied by the question How strong is the causal claim?"
    }
  ],
  "differentiation_and_accessibility": {
    "support": [
      "Provide a word bank and a partially labeled network diagram.",
      "Preteach vmPFC, OFC, ACC, striatum, and prediction error.",
      "Use sentence frames such as: This system may contribute to... because... followed by this evidence.",
      "Allow students to explain their concept map orally or through labeled images.",
      "Provide calculators for prediction-error practice."
    ],
    "extension": [
      "Ask advanced students to compare goal-directed and habitual control using a reinforcement-learning model.",
      "Have students analyze how lesion location, disease progression, or compensatory strategies can alter study findings.",
      "Ask students to design a computational model that combines evidence, value, and action thresholds."
    ],
    "accessibility": [
      "Do not rely on color alone to encode arrows or functions.",
      "Provide descriptive text for all diagrams.",
      "Use large, high-contrast text and clear symbols.",
      "Break complex instructions into sequential steps.",
      "Allow written, oral, or visual responses where appropriate."
    ]
  },
  "teacher_facilitation_notes": [
    "If a student says that the prefrontal cortex is the only decision-making region, ask which structures could maintain a goal, assign value, and select an action.",
    "If a student says dopamine produces pleasure, contrast the reward value of an outcome with dopamine's role in prediction and learning.",
    "If a student interprets stronger activation as preference, ask whether the region might instead be monitoring difficulty or conflict.",
    "If a student treats the prediction-error equation as a complete model of dopamine function, state that it is a simplified teaching model.",
    "If time is limited, shorten the debate while preserving the network map, evidence case, and exit ticket."
  ],
  "scientific_accuracy_and_ethics": [
    "Use distributed-network language rather than naming a single decision-making center.",
    "Treat all brain diagrams as simplified models that do not preserve exact anatomy or scale.",
    "Label the case study as hypothetical and avoid presenting it as a diagnostic brain scan.",
    "State that fMRI findings are correlational unless supported by experimental manipulation.",
    "Present the reward prediction-error account as a useful simplified model rather than a complete description of every dopamine neuron.",
    "Avoid simplistic left-brain versus right-brain or emotion versus reason explanations."
  ],
  "suggested_references": [
    {
      "reference": "Schultz W, Dayan P, and Montague PR. A Neural Substrate of Prediction and Reward. Science, 1997, 275:1593–1599.",
      "use": "Dopamine prediction-error account"
    },
    {
      "reference": "Montague PR, Dayan P, and Schultz W. A Theory of Dopamine-Based Reinforcement Learning. Neural Networks, 2006, 19:1065–1089.",
      "use": "Computational interpretation of dopamine and reinforcement learning"
    },
    {
      "reference": "Kandel ER et al. Principles of Neural Science.",
      "use": "Background on prefrontal, basal-ganglia, and dopamine systems"
    },
    {
      "reference": "Purves C et al. Neuroscience.",
      "use": "Introductory reference for neural circuits and research methods"
    }
  ]
}

{
  "teaching_material": {
